#!/usr/bin/env python3

from __future__ import annotations

import argparse
import json
import shutil
from pathlib import Path


def _load_repo_runtime_bootstrap():
    pathlib, sys = __import__("pathlib"), __import__("sys")
    marker = ("scripts", "adapter_lib.py")
    parents = pathlib.Path(__file__).resolve().parents
    root = next((p for p in parents if p.joinpath(*marker).is_file()), None)
    if root is not None and str(root) not in sys.path:
        sys.path.insert(0, str(root))


_load_repo_runtime_bootstrap()

from scripts.runtime_bootstrap import import_repo_module, repo_root_from_script  # noqa: E402
from scripts.runtime_scratch import owned_scratch  # noqa: E402
from scripts.yaml_output import emit_yaml  # noqa: E402

_subprocess_guard = import_repo_module(__file__, "scripts.core.subprocess_guard")
run_process = _subprocess_guard.run_process
_quality_universes = import_repo_module(__file__, "scripts.adapters.quality_universes_lib")
_quality_adapter = import_repo_module(__file__, "scripts.adapters.quality_adapter_lib")
DEFAULT_UNIVERSES = _quality_universes.DEFAULT_UNIVERSES
Universe = _quality_universes.Universe
matching_files = _quality_universes.matching_files
refuse_if_declared_and_empty = _quality_universes.refuse_if_declared_and_empty
resolve_universe = _quality_universes.resolve_universe
load_quality_adapter = _quality_adapter.load_quality_adapter

try:
    from scripts.core.repo_file_listing import iter_repo_files
except ModuleNotFoundError:
    from scripts.core.repo_file_listing import iter_repo_files

IGNORED_DIRS = {
    ".artifacts",
    ".git",
    ".mypy_cache",
    ".pytest_cache",
    ".ruff_cache",
    ".venv",
    "__pycache__",
    "evals",
    "node_modules",
    "plugins",
}
DEFAULT_MAX_RATIO = 1.0
SUPPORTED_ENGINES = ("auto", "splitlines", "tokei")
SURFACE_BUCKETS = (
    "python",
    "python-shebang",
    "shell",
    "rust",
    "rust-tests",
    "tests-python",
)
TOKEI_TYPES = "Python,Shell,Rust"
SKIPPED_PYTHON_REASON = "unreadable-python-source"


class RatioError(Exception):
    pass


class TokeiUnavailableError(RuntimeError):
    pass


def _relative_parts(path: Path, repo_root: Path) -> tuple[str, ...]:
    return path.relative_to(repo_root).parts


def _is_native_fixture(relative_parts: tuple[str, ...]) -> bool:
    return (
        len(relative_parts) >= 3
        and relative_parts[0] == "native"
        and relative_parts[2] == "fixtures"
    )


def _is_ignored_source_path(relative_parts: tuple[str, ...]) -> bool:
    return any(part in IGNORED_DIRS for part in relative_parts[:-1]) or _is_native_fixture(
        relative_parts
    )


def _is_python_shebang(path: Path) -> bool:
    try:
        with path.open("r", encoding="utf-8") as source:
            first_line = source.readline().rstrip("\n\r")
    except (OSError, UnicodeDecodeError):
        return False
    if not first_line.startswith("#!"):
        return False
    interpreter_parts = first_line[2:].strip().split()
    if not interpreter_parts:
        return False
    interpreter = interpreter_parts[0]
    if Path(interpreter).name == "env":
        interpreter = next((part for part in interpreter_parts[1:] if not part.startswith("-")), "")
    interpreter_name = Path(interpreter).name.lower()
    version = interpreter_name.removeprefix("python")
    return interpreter_name.startswith("python") and (
        not version or version.replace(".", "").isdigit()
    )


def _resolved_test_universe(
    repo_root: Path, *, require_git: bool = False
) -> tuple[Universe, list[Path]]:
    adapter = load_quality_adapter(repo_root)
    if adapter.get("valid") is False:
        errors = "; ".join(str(error) for error in adapter.get("errors", []))
        raise SystemExit(
            "check-test-production-ratio: quality adapter is invalid"
            f"{f': {errors}' if errors else '.'}"
        )
    universe = resolve_universe(
        adapter,
        "test_roots",
        default=DEFAULT_UNIVERSES["test_roots"],
    )
    try:
        files = matching_files(repo_root, universe, require_git=require_git)
    except RuntimeError as exc:
        raise SystemExit(str(exc)) from exc
    refusal = refuse_if_declared_and_empty(universe, files, "check-test-production-ratio")
    if refusal is not None:
        raise SystemExit(refusal)
    return universe, files


def _surface_files(
    repo_root: Path,
    *,
    require_git: bool = False,
    test_paths: set[Path] | None = None,
) -> dict[str, list[Path]]:
    """Return the one shared file inventory used by both line-counting engines.

    Python keeps the historical repository listing, including non-ignored
    untracked files. The newly admitted extensionless, shell, and Rust surfaces
    use tracked files when Git is available. YAML/JSON/TOML are intentionally
    absent: they are policy/configuration data, not executable source. Native
    crate fixtures are also absent in every bucket, including their Python files.
    """

    if test_paths is None:
        _test_universe, test_files = _resolved_test_universe(repo_root, require_git=require_git)
        test_paths = set(test_files)
    all_files = iter_repo_files(repo_root, include_untracked=True, require_git=require_git)
    tracked_files = iter_repo_files(repo_root, include_untracked=False, require_git=require_git)

    source_python: list[Path] = []
    test_python: list[Path] = []
    for path in all_files:
        relative_parts = _relative_parts(path, repo_root)
        if path.suffix == ".py":
            if path in test_paths:
                test_python.append(path)
            elif not _is_ignored_source_path(relative_parts):
                source_python.append(path)

    surface: dict[str, list[Path]] = {
        "python": sorted(source_python),
        "python-shebang": [],
        "shell": [],
        "rust": [],
        "rust-tests": [],
        "tests-python": sorted(test_python),
    }
    for path in tracked_files:
        relative_parts = _relative_parts(path, repo_root)
        if _is_native_fixture(relative_parts):
            continue
        if (
            len(relative_parts) >= 4
            and relative_parts[0] == "native"
            and relative_parts[2] == "tests"
            and path.suffix == ".rs"
        ):
            surface["rust-tests"].append(path)
            continue
        if _is_ignored_source_path(relative_parts):
            continue
        if path.suffix == "" and _is_python_shebang(path):
            surface["python-shebang"].append(path)
        if path.suffix == ".sh" or ".githooks" in relative_parts[:-1]:
            surface["shell"].append(path)
        if (
            len(relative_parts) >= 4
            and relative_parts[0] == "native"
            and relative_parts[2] == "src"
            and path.suffix == ".rs"
        ) or (
            len(relative_parts) == 3 and relative_parts[0] == "native" and path.name == "build.rs"
        ):
            surface["rust"].append(path)
    return {bucket: sorted(paths) for bucket, paths in surface.items()}


def _surface_file_names(
    surface_files: dict[str, list[Path]], repo_root: Path
) -> dict[str, list[str]]:
    return {
        bucket: [path.relative_to(repo_root).as_posix() for path in paths]
        for bucket, paths in surface_files.items()
    }


def count_lines(paths: list[Path], *, skipped_paths: list[Path] | None = None) -> int:
    lines = 0
    for path in paths:
        try:
            contents = path.read_text(encoding="utf-8")
            if "\x00" in contents:
                raise ValueError("Python source contains a null byte")
            lines += len(contents.splitlines())
        except (OSError, UnicodeDecodeError, ValueError):
            if skipped_paths is not None:
                skipped_paths.append(path)
    return lines


def _splitlines_summary(
    repo_root: Path, *, require_git: bool = False, test_paths: set[Path] | None = None
) -> dict[str, object]:
    surface_files = _surface_files(repo_root, require_git=require_git, test_paths=test_paths)
    skipped_paths: list[Path] = []
    line_counts = {
        bucket: count_lines(paths, skipped_paths=skipped_paths)
        for bucket, paths in surface_files.items()
    }
    source_lines = sum(line_counts[bucket] for bucket in SURFACE_BUCKETS[:4])
    test_lines = sum(line_counts[bucket] for bucket in SURFACE_BUCKETS[4:])
    return {
        "source_lines": source_lines,
        "test_lines": test_lines,
        "source_file_count": sum(len(surface_files[bucket]) for bucket in SURFACE_BUCKETS[:4]),
        "test_file_count": sum(len(surface_files[bucket]) for bucket in SURFACE_BUCKETS[4:]),
        "surface_breakdown": line_counts,
        "surface_file_buckets": _surface_file_names(surface_files, repo_root),
        "skipped_paths": sorted(path.relative_to(repo_root).as_posix() for path in skipped_paths),
    }


def _ensure_tokei_available() -> None:
    if shutil.which("tokei") is None:
        raise TokeiUnavailableError(
            "tokei binary not found on PATH; install per integrations/tools/tokei.json or "
            "fall back to --engine splitlines."
        )


def _tokei_code(paths: list[Path], *, language: str, repo_root: Path) -> tuple[int, set[Path]]:
    """Count an exact path list with tokei and return its reported files."""

    cmd = [
        "tokei",
        "--output",
        "json",
        "--types",
        TOKEI_TYPES,
        "--no-ignore",
        "--hidden",
        *(str(path) for path in paths),
    ]
    completed = run_process(cmd, cwd=repo_root, timeout_seconds=None)
    if completed.returncode != 0:
        raise TokeiUnavailableError(
            f"tokei exited with status {completed.returncode}: {completed.stderr.strip()}"
        )
    try:
        payload = json.loads(completed.stdout)
    except json.JSONDecodeError as exc:
        raise TokeiUnavailableError(f"tokei returned invalid JSON: {exc}") from exc
    details = payload.get(language)
    if not isinstance(details, dict):
        return 0, set()
    reports = details.get("reports", [])
    if not isinstance(reports, list):
        raise TokeiUnavailableError(f"tokei returned an invalid {language} reports list")
    reported_paths: set[Path] = set()
    for report in reports:
        if not isinstance(report, dict) or not isinstance(report.get("name"), str):
            raise TokeiUnavailableError(f"tokei returned an invalid {language} report")
        report_path = Path(report["name"])
        if not report_path.is_absolute():
            report_path = repo_root / report_path
        reported_paths.add(report_path.resolve())
    return int(details.get("code", 0)), reported_paths


def _tokei_bucket_code(
    paths: list[Path], *, bucket: str, language: str, repo_root: Path
) -> tuple[int, dict[str, object] | None]:
    if not paths:
        return 0, None
    code, reported_paths = _tokei_code(paths, language=language, repo_root=repo_root)
    missing_paths = [path for path in paths if path.resolve() not in reported_paths]
    if not missing_paths:
        return code, None

    # Tokei 14 detects the extensionless Python shebang but does not classify
    # extensionless Bash hooks. Re-present any missed selected file with the
    # known language extension so the adjustment still uses tokei's code count,
    # while keeping the original file in the measured set.
    suffix = {"Python": ".py", "Shell": ".sh", "Rust": ".rs"}[language]
    with owned_scratch(repo_root, "test-production-ratio") as temp_dir:
        remapped_paths: list[Path] = []
        for index, path in enumerate(missing_paths):
            remapped = Path(temp_dir) / f"{index}{suffix}"
            shutil.copyfile(path, remapped)
            remapped_paths.append(remapped)
        adjusted_code, adjusted_reported_paths = _tokei_code(
            remapped_paths, language=language, repo_root=repo_root
        )
    if len(adjusted_reported_paths) != len(missing_paths):
        missing = ", ".join(path.relative_to(repo_root).as_posix() for path in missing_paths)
        raise TokeiUnavailableError(f"tokei did not classify selected {bucket} files: {missing}")
    return code + adjusted_code, {
        "files": [path.relative_to(repo_root).as_posix() for path in missing_paths],
        "code_lines": adjusted_code,
        "method": "tokei-explicit-extension",
    }


def _tokei_summary(
    repo_root: Path, *, require_git: bool = False, test_paths: set[Path] | None = None
) -> dict[str, object]:
    _ensure_tokei_available()
    surface_files = _surface_files(repo_root, require_git=require_git, test_paths=test_paths)
    languages = {
        "python": "Python",
        "python-shebang": "Python",
        "shell": "Shell",
        "rust": "Rust",
        "rust-tests": "Rust",
        "tests-python": "Python",
    }
    line_counts: dict[str, int] = {}
    adjustments: dict[str, dict[str, object]] = {}
    for bucket in SURFACE_BUCKETS:
        code, adjustment = _tokei_bucket_code(
            surface_files[bucket],
            bucket=bucket,
            language=languages[bucket],
            repo_root=repo_root,
        )
        line_counts[bucket] = code
        if adjustment is not None:
            adjustments[bucket] = adjustment
    surface_breakdown: dict[str, object] = dict(line_counts)
    if adjustments:
        surface_breakdown["tokei_adjustments"] = adjustments
    return {
        "source_lines": sum(line_counts[bucket] for bucket in SURFACE_BUCKETS[:4]),
        "test_lines": sum(line_counts[bucket] for bucket in SURFACE_BUCKETS[4:]),
        "source_file_count": sum(len(surface_files[bucket]) for bucket in SURFACE_BUCKETS[:4]),
        "test_file_count": sum(len(surface_files[bucket]) for bucket in SURFACE_BUCKETS[4:]),
        "surface_breakdown": surface_breakdown,
        "surface_file_buckets": _surface_file_names(surface_files, repo_root),
    }


def _resolve_engine(engine: str) -> tuple[str, str]:
    if engine not in SUPPORTED_ENGINES:
        raise ValueError(f"unsupported engine {engine!r}; expected one of {SUPPORTED_ENGINES}")
    if engine == "auto":
        return ("tokei" if shutil.which("tokei") is not None else "splitlines", "auto")
    return engine, "explicit"


def summarize(
    repo_root: Path, *, engine: str = "auto", require_git: bool = False
) -> dict[str, object]:
    test_universe, test_files = _resolved_test_universe(repo_root, require_git=require_git)
    resolved_engine, engine_selection = _resolve_engine(engine)
    if resolved_engine == "tokei":
        counts = _tokei_summary(repo_root, require_git=require_git, test_paths=set(test_files))
    else:
        counts = _splitlines_summary(repo_root, require_git=require_git, test_paths=set(test_files))
    source_lines = int(counts["source_lines"])
    test_lines = int(counts["test_lines"])
    ratio = test_lines / source_lines if source_lines else 0.0
    return {
        "schema_version": 1,
        "scope": "executable-surface",
        "engine": resolved_engine,
        "engine_selection": engine_selection,
        "source_lines": source_lines,
        "test_lines": test_lines,
        "ratio": round(ratio, 4),
        "surface_breakdown": counts["surface_breakdown"],
        "source_file_count": counts["source_file_count"],
        "test_file_count": counts["test_file_count"],
        "test_roots": {
            "patterns": list(test_universe.patterns),
            "source": test_universe.source,
            "matched_files": len(test_files),
            "status": "configured" if test_files else "discovered-empty",
        },
        "excluded_source_dirs": sorted(IGNORED_DIRS),
        "skipped": {
            "status": "skipped",
            "reason": SKIPPED_PYTHON_REASON,
            "count": len(counts.get("skipped_paths", [])),
            "paths": counts.get("skipped_paths", []),
        },
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo-root", type=Path, default=repo_root_from_script(__file__))
    parser.add_argument("--max-ratio", type=float, default=DEFAULT_MAX_RATIO)
    parser.add_argument("--engine", choices=SUPPORTED_ENGINES, default="auto")
    parser.add_argument("--require-git-file-listing", action="store_true")
    parser.add_argument(
        "--advisory",
        action="store_true",
        help=(
            "report an over-threshold ratio as a non-blocking WARN posture instead of "
            "failing. A test/production LOC ratio is a smell sensor, not an "
            "irreversible-boundary contract (north-star P1); a hard cap pressures "
            "AGAINST writing tests as the ratio approaches it. The posture stays "
            "visible; judgment owns the split-vs-bloat call."
        ),
    )
    args = parser.parse_args()

    try:
        summary = summarize(
            args.repo_root.resolve(),
            engine=args.engine,
            require_git=args.require_git_file_listing,
        )
    except TokeiUnavailableError as exc:
        print(str(exc))
        return 2
    # `max_ratio` lived ONLY in the deleted human line -- the summary payload never
    # carried the bar the ratio is judged against, so a bare `ratio: 0.87` said
    # nothing about whether it passed. Output is unconditionally YAML now, so the
    # bar, the verdict and the advisory posture all ride on the payload.
    payload = {**summary, "max_ratio": args.max_ratio}
    over = float(summary["ratio"]) > args.max_ratio
    message = f"test-production ratio {summary['ratio']:.2f} exceeds max {args.max_ratio:.2f}"
    if over and args.advisory:
        payload["status"] = "advisory-warn"
        payload["advisory"] = f"WARN: {message} (advisory posture; not blocking)"
    else:
        payload["status"] = "over-max" if over else "within-max"
    emit_yaml(payload)
    if over:
        if args.advisory:
            return 0
        raise RatioError(message)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except RatioError as exc:
        print(str(exc))
        raise SystemExit(1)

"""Critique adapter loader + validator.

The adapter is optional. Without it, `critique` runs with inferred
defaults and consumes no prepare packet. With one or more
`packet_sections` declared, the prepare runner becomes the consumer
contract for fresh-eye reviewers.

Schema lives in
`skills/public/critique/references/adapter-contract.md`.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any


def _load_repo_runtime_bootstrap():
    pathlib, sys = __import__("pathlib"), __import__("sys")
    marker = ("scripts", "adapter_lib.py")
    parents = pathlib.Path(__file__).resolve().parents
    root = next((p for p in parents if p.joinpath(*marker).is_file()), None)
    if root is not None and str(root) not in sys.path:
        sys.path.insert(0, str(root))


_load_repo_runtime_bootstrap()

from scripts.adapter_lib import (  # noqa: E402
    declared_fields_after_version_check,
    optional_string,
    resolve_adapter_payload,
)

DEFAULT_OUTPUT_DIR = "charness-artifacts/critique"
ADAPTER_CANDIDATES = (
    Path(".agents/critique-adapter.yaml"),
)
STRING_FIELDS = ("repo", "language", "output_dir")
VALID_CONTENT_KINDS = ("static", "script")
VALID_REVIEWER_TIERS = ("high-leverage", "medium", "standard")
REVIEWER_TIER_FIELDS = ("model", "reasoning_effort", "service_tier", "fork_turns")
VALID_REVIEWER_RUNNER_MODES = ("file-backed-worker", "typed-subagent")
VALID_REVIEWER_BACKENDS = ("codex_exec", "claude_p", "host-defaulted")
REVIEWER_RUNNER_FIELDS = ("mode", "backend", "timeout_seconds")
FOLLOW_UP_SCOPE_MODES = ("selected-paths", "static")


def infer_repo_defaults(repo_root: Path) -> dict[str, Any]:
    return {
        "version": 1,
        "repo": repo_root.name,
        "language": "en",
        "output_dir": DEFAULT_OUTPUT_DIR,
        "packet_sections": [],
        "reviewer_runner": {
            "mode": "file-backed-worker",
            "backend": "host-defaulted",
            "timeout_seconds": 900,
        },
    }


def _validate_section_identity(
    raw: dict[str, Any],
    *,
    field: str,
    seen_ids: set[str],
    errors: list[str],
) -> dict[str, Any]:
    section: dict[str, Any] = {}
    section_id = optional_string(raw.get("id"), f"{field}.id", errors)
    if section_id is None:
        errors.append(f"{field}.id is required")
    else:
        if section_id in seen_ids:
            errors.append(f"{field}.id duplicates earlier section `{section_id}`")
        else:
            seen_ids.add(section_id)
        section["id"] = section_id
    title = optional_string(raw.get("title"), f"{field}.title", errors)
    if title is None:
        errors.append(f"{field}.title is required")
    else:
        section["title"] = title
    return section


def _validate_section_kind(
    raw: dict[str, Any], *, field: str, errors: list[str]
) -> str | None:
    content_kind = optional_string(raw.get("content_kind"), f"{field}.content_kind", errors)
    if content_kind is None:
        errors.append(f"{field}.content_kind is required")
        return None
    if content_kind not in VALID_CONTENT_KINDS:
        errors.append(
            f"{field}.content_kind must be one of: {', '.join(VALID_CONTENT_KINDS)}"
        )
        return None
    return content_kind


def _validate_section_payload(
    raw: dict[str, Any],
    *,
    field: str,
    content_kind: str | None,
    errors: list[str],
) -> dict[str, Any] | None:
    populated_fields = [name for name in ("content", "content_path", "command") if name in raw]
    if len(populated_fields) != 1:
        errors.append(
            f"{field} must declare exactly one of `content`, `content_path`, `command`; "
            f"got {populated_fields or 'none'}"
        )
        return None
    populated = populated_fields[0]
    if content_kind == "script" and populated != "command":
        errors.append(f"{field}.content_kind=script requires `command`, not `{populated}`")
        return None
    if content_kind == "static" and populated == "command":
        errors.append(f"{field}.content_kind=static requires `content` or `content_path`, not `command`")
        return None
    if populated == "command":
        command = optional_string(raw.get("command"), f"{field}.command", errors)
        if not command:
            errors.append(f"{field}.command must be a non-empty string")
            return None
        return {"command": command}
    if populated == "content_path":
        content_path = optional_string(raw.get("content_path"), f"{field}.content_path", errors)
        if not content_path:
            errors.append(f"{field}.content_path must be a non-empty string")
            return None
        return {"content_path": content_path}
    content = raw.get("content")
    if isinstance(content, str):
        return {"content": content}
    if isinstance(content, list) and all(isinstance(item, str) for item in content):
        return {"content": "\n".join(content)}
    errors.append(f"{field}.content must be a string or list of strings")
    return None


def _validate_section(
    raw: Any,
    *,
    index: int,
    seen_ids: set[str],
    errors: list[str],
) -> dict[str, Any] | None:
    field = f"packet_sections[{index}]"
    if not isinstance(raw, dict):
        errors.append(f"{field} must be a mapping")
        return None
    section = _validate_section_identity(raw, field=field, seen_ids=seen_ids, errors=errors)
    content_kind = _validate_section_kind(raw, field=field, errors=errors)
    if content_kind is not None:
        section["content_kind"] = content_kind
    payload = _validate_section_payload(raw, field=field, content_kind=content_kind, errors=errors)
    if payload is None:
        return None
    section.update(payload)
    return section


def _validate_reviewer_tiers(
    raw: Any, *, errors: list[str], warnings: list[str]
) -> dict[str, Any] | None:
    if not isinstance(raw, dict):
        errors.append("reviewer_tiers must be a mapping")
        return None
    tiers: dict[str, Any] = {}
    for name, spec in raw.items():
        field = f"reviewer_tiers.{name}"
        if not isinstance(spec, dict):
            errors.append(f"{field} must be a mapping")
            continue
        if name not in VALID_REVIEWER_TIERS:
            warnings.append(
                f"{field} is not a known reviewer tier "
                f"({', '.join(VALID_REVIEWER_TIERS)})"
            )
        entry: dict[str, str] = {}
        for key, value in spec.items():
            if key not in REVIEWER_TIER_FIELDS:
                errors.append(
                    f"{field}.{key} is not a valid reviewer-tier field "
                    f"({', '.join(REVIEWER_TIER_FIELDS)})"
                )
                continue
            text = optional_string(value, f"{field}.{key}", errors)
            if text is not None:
                entry[key] = text
        tiers[name] = entry
    return tiers


def _validate_reviewer_runner(raw: Any, *, errors: list[str]) -> dict[str, Any] | None:
    if not isinstance(raw, dict):
        errors.append("reviewer_runner must be a mapping")
        return None
    for key in sorted(set(raw) - set(REVIEWER_RUNNER_FIELDS)):
        errors.append(
            f"reviewer_runner.{key} is not a valid runner field "
            f"({', '.join(REVIEWER_RUNNER_FIELDS)})"
        )
    mode = optional_string(raw.get("mode"), "reviewer_runner.mode", errors)
    backend = optional_string(raw.get("backend"), "reviewer_runner.backend", errors)
    timeout = raw.get("timeout_seconds", 900)
    if not isinstance(timeout, int) or isinstance(timeout, bool) or timeout <= 0:
        errors.append("reviewer_runner.timeout_seconds must be a positive integer")
        timeout = 900
    if mode is not None and mode not in VALID_REVIEWER_RUNNER_MODES:
        errors.append(
            f"reviewer_runner.mode must be one of: {', '.join(VALID_REVIEWER_RUNNER_MODES)}"
        )
    if backend is not None and backend not in VALID_REVIEWER_BACKENDS:
        errors.append(
            f"reviewer_runner.backend must be one of: {', '.join(VALID_REVIEWER_BACKENDS)}"
        )
    return {
        "mode": mode or "file-backed-worker",
        "backend": backend or "host-defaulted",
        "timeout_seconds": timeout,
    }


def _validate_follow_up_scope(raw: Any, *, errors: list[str]) -> list[dict[str, Any]] | None:
    if not isinstance(raw, list):
        errors.append("follow_up_scope must be a list")
        return None
    validated: list[dict[str, Any]] = []
    seen: set[str] = set()
    for index, item in enumerate(raw):
        field = f"follow_up_scope[{index}]"
        if not isinstance(item, dict):
            errors.append(f"{field} must be a mapping")
            continue
        section_id = optional_string(item.get("section_id"), f"{field}.section_id", errors)
        mode = optional_string(item.get("mode"), f"{field}.mode", errors)
        binding = optional_string(item.get("binding"), f"{field}.binding", errors)
        path_binding = optional_string(item.get("path_binding"), f"{field}.path_binding", errors)
        if section_id is None or mode is None or binding is None:
            continue
        if section_id in seen:
            errors.append(f"{field}.section_id duplicates `{section_id}`")
        seen.add(section_id)
        if mode not in FOLLOW_UP_SCOPE_MODES:
            errors.append(
                f"{field}.mode must be one of: {', '.join(FOLLOW_UP_SCOPE_MODES)}"
            )
            continue
        if mode == "selected-paths" and path_binding != "exact-path-manifest":
            errors.append(
                f"{field}.path_binding must be `exact-path-manifest` for selected-paths sections"
            )
        validated.append(
            {
                "section_id": section_id,
                "mode": mode,
                "binding": binding,
                "path_binding": path_binding,
            }
        )
    return validated


def validate_adapter_data(  # noqa: C901
    data: dict[str, Any], repo_root: Path
) -> tuple[dict[str, Any], list[str], list[str]]:
    errors: list[str] = []
    warnings: list[str] = []
    validated = infer_repo_defaults(repo_root)

    data = declared_fields_after_version_check(data, validated, errors)

    for field in STRING_FIELDS:
        value = optional_string(data.get(field), field, errors)
        if value is not None:
            validated[field] = value

    sections_raw = data.get("packet_sections")
    if sections_raw is None:
        pass
    elif not isinstance(sections_raw, list):
        errors.append("packet_sections must be a list")
    else:
        seen_ids: set[str] = set()
        sections: list[dict[str, Any]] = []
        for index, raw_section in enumerate(sections_raw):
            section = _validate_section(
                raw_section, index=index, seen_ids=seen_ids, errors=errors
            )
            if section is not None:
                sections.append(section)
        validated["packet_sections"] = sections

    tiers_raw = data.get("reviewer_tiers")
    if tiers_raw is not None:
        tiers = _validate_reviewer_tiers(tiers_raw, errors=errors, warnings=warnings)
        if tiers is not None:
            validated["reviewer_tiers"] = tiers

    runner_raw = data.get("reviewer_runner")
    if runner_raw is not None:
        runner = _validate_reviewer_runner(runner_raw, errors=errors)
        if runner is not None:
            validated["reviewer_runner"] = runner

    follow_up_scope_raw = data.get("follow_up_scope")
    if follow_up_scope_raw is not None:
        follow_up_scope = _validate_follow_up_scope(follow_up_scope_raw, errors=errors)
        if follow_up_scope is not None:
            validated["follow_up_scope"] = follow_up_scope

    # Repo-owned cross-surface probe for the boundary-ownership checkpoint
    # (#408). The critique validator's severity upgrade reads these through this
    # one adapter. Keys mirror scripts/evidence/boundary_probe_lib.py
    # (BOUNDARY_GLOBS_KEY / BOUNDARY_SURFACES_KEY).
    for key in ("boundary_cross_surface_globs", "boundary_cross_surface_surfaces"):
        raw_list = data.get(key)
        if raw_list is None:
            continue
        # `[]` is the explicit-empty spelling, and it is the ONLY one. A bare `key:`
        # parses to an empty MAPPING, which is deliberately refused here: the parser
        # also renders `key:` followed by dash-less children as `{}` (each child has no
        # mapping separator, so it is silently dropped), and accepting `{}` as an
        # opt-out would read a probe config the author clearly meant to declare as a
        # deliberate "no probe" -- exit 0 over a broken config, which is the defect this
        # whole surface exists to remove. Measured: `list_field_state` classifies `{}`
        # as `configured` and only `[]` as `explicit-empty`, and this repo's own adapter
        # spells the empty declaration `boundary_cross_surface_surfaces: []`.
        if isinstance(raw_list, list) and all(isinstance(item, str) for item in raw_list):
            validated[key] = list(raw_list)
        else:
            errors.append(f"{key} must be a list of strings")

    if data.get("repo") == "CHANGE_ME":
        warnings.append("repo is still set to CHANGE_ME")

    return validated, errors, warnings


def load_adapter(repo_root: Path) -> dict[str, Any]:
    # `resolve_adapter_payload`, NOT a hand-written pair of branches around
    # `load_yaml_file`. The bare loader RAISES on a document the parser refuses and DISCARDS
    # the uninterpreted-line sink, so `parse_refused` and `declarations_dropped` were both
    # structurally dead for this skill's consumers (#673).
    return resolve_adapter_payload(
        repo_root,
        candidates=ADAPTER_CANDIDATES,
        infer_defaults=infer_repo_defaults,
        validate=validate_adapter_data,
        absent_warnings=lambda _data: [
            "No critique adapter found. The prepare-packet contract is opt-in;"
            " critique runs with inferred defaults and no packet consumption.",
        ],
    )


def adapter_has_sections(adapter: dict[str, Any]) -> bool:
    """The opt-in signal: at least one declared packet section."""
    sections = adapter.get("data", {}).get("packet_sections", [])
    return bool(sections)

"""Adapter-declared producer scope checks for critique follow-up packets."""

from __future__ import annotations

import hashlib
from typing import Any, Callable


def _path_set_digest(paths: list[str]) -> str:
    return hashlib.sha256("\n".join(sorted(set(paths))).encode("utf-8")).hexdigest()


def _manifest_paths(content: str) -> list[str] | None:
    lines = content.splitlines()
    try:
        start = lines.index("Exact reviewed-path manifest:") + 1
    except ValueError:
        return None
    paths: list[str] = []
    for line in lines[start:]:
        if not line:
            break
        if not line.startswith("- "):
            return None
        value = line[2:]
        value = value.split("  (DELETED", 1)[0]
        if value and not value.startswith("("):
            paths.append(value)
    return paths


def follow_up_scope_receipt(
    *,
    adapter: dict[str, Any],
    sections: list[dict[str, Any]],
    selected_paths: list[str],
    error: Callable[..., Exception],
) -> dict[str, Any]:
    """Verify and record how every follow-up section was narrowed."""
    declarations = (adapter.get("data", {}) or {}).get("follow_up_scope", [])
    if not isinstance(declarations, list):
        raise error(
            "follow-up-scope-unbound",
            "follow_up_scope must be a list of per-section declarations",
        )
    by_id = {
        item.get("section_id"): item
        for item in declarations
        if isinstance(item, dict) and isinstance(item.get("section_id"), str)
    }
    expected_ids = {
        section.get("id") for section in sections if isinstance(section.get("id"), str)
    }
    if set(by_id) != expected_ids:
        raise error(
            "follow-up-scope-unbound",
            "follow_up_scope must declare every packet section exactly once",
            details={
                "declared_section_ids": sorted(by_id),
                "packet_section_ids": sorted(expected_ids),
                "missing_section_ids": sorted(expected_ids - set(by_id)),
                "unexpected_section_ids": sorted(set(by_id) - expected_ids),
            },
        )

    selected = sorted(set(selected_paths))
    receipts: list[dict[str, Any]] = []
    for section in sections:
        section_id = section["id"]
        declaration = by_id[section_id]
        mode = declaration.get("mode")
        if mode not in {"selected-paths", "static"}:
            raise error(
                "follow-up-scope-unbound",
                f"follow-up_scope mode is invalid for section `{section_id}`",
                details={"section_id": section_id, "mode": mode},
            )
        content = section.get("content") if isinstance(section.get("content"), str) else ""
        path_set_digest = None
        if mode == "selected-paths":
            if declaration.get("path_binding") != "exact-path-manifest":
                raise error(
                    "follow-up-producer-out-of-scope",
                    f"follow-up producer section `{section_id}` has no exact path binding",
                )
            manifest_paths = _manifest_paths(content)
            if manifest_paths is None or sorted(set(manifest_paths)) != selected:
                raise error(
                    "follow-up-producer-out-of-scope",
                    f"follow-up producer section `{section_id}` path manifest is not exact",
                    details={
                        "section_id": section_id,
                        "expected_paths": selected,
                        "actual_paths": sorted(set(manifest_paths or [])),
                    },
                )
            path_set_digest = _path_set_digest(selected)
        receipts.append(
            {
                "section_id": section_id,
                "mode": mode,
                "binding": declaration.get("binding"),
                "path_binding": declaration.get("path_binding"),
                "selected_path_count": len(selected),
                "path_set_sha256": path_set_digest,
                "status": "verified",
                "path_check": "exact-manifest" if mode == "selected-paths" else "not-applicable",
            }
        )
    return {
        "kind": "charness.follow_up_scope_receipt.v1",
        "status": "verified",
        "selected_paths": selected,
        "sections": receipts,
        "contract": (
            "Adapter-declared follow-up scope; selected-path sections must expose every "
            "identity-bound path, and static sections must declare that they are not path-bearing."
        ),
    }

#!/usr/bin/env python3
"""Default `changed-files-and-owning-surfaces` producer for prepare packets.

Stdout body lists each path in the current working set and the surfaces
(from `.agents/surfaces.json`) that own or derive from it. The output
shape is the *section body*; the runner wraps this into the packet
envelope. Exit 0 even when the working set is empty.

See `skills/public/critique/references/prepare-packet.md` and the retro
prepare-packet sibling.
"""
from __future__ import annotations

import argparse
import json
import os
from pathlib import Path


def _load_repo_runtime_bootstrap():
    pathlib, sys = __import__("pathlib"), __import__("sys")
    marker = ("scripts", "adapter_lib.py")
    parents = pathlib.Path(__file__).resolve().parents
    root = next((p for p in parents if p.joinpath(*marker).is_file()), None)
    if root is not None and str(root) not in sys.path:
        sys.path.insert(0, str(root))


_load_repo_runtime_bootstrap()

from scripts.runtime_bootstrap import import_repo_module, repo_root_from_script  # noqa: E402

REPO_ROOT = repo_root_from_script(__file__)

_scripts_surfaces_lib_module = import_repo_module(__file__, "scripts.adapters.surfaces_lib")
SurfaceError = _scripts_surfaces_lib_module.SurfaceError
collect_working_tree_snapshot = _scripts_surfaces_lib_module.collect_working_tree_snapshot
collect_changed_and_deleted_paths_for_ref = (
    _scripts_surfaces_lib_module.collect_changed_and_deleted_paths_for_ref
)
load_surfaces = _scripts_surfaces_lib_module.load_surfaces
match_surfaces = _scripts_surfaces_lib_module.match_surfaces


def _declared_review_paths() -> list[str] | None:
    raw = os.environ.get("CHARNESS_CRITIQUE_REVIEWED_PATHS")
    if raw is None:
        return None
    try:
        value = json.loads(raw)
    except json.JSONDecodeError:
        return []
    if not isinstance(value, list):
        return []
    return sorted({item for item in value if isinstance(item, str) and item})


def _render_paths(payload: dict[str, object]) -> list[str]:
    lines: list[str] = []
    changed_paths = payload["changed_paths"]
    changed_ref = payload.get("changed_ref")
    if payload.get("narrowed"):
        if changed_ref:
            prefix = f"Bound review paths for ref `{changed_ref}`: (narrow follow-up scope)"
        else:
            prefix = "Bound review paths for working tree: (narrow follow-up scope)"
    elif changed_ref:
        prefix = f"Changed paths for ref `{changed_ref}`:"
    else:
        prefix = "Changed paths for working tree:"
    lines.append(prefix)
    lines.append("Exact reviewed-path manifest:")
    deleted_paths = set(payload.get("deleted_paths") or ())
    if changed_paths:
        for path in changed_paths:
            # A removal rendered exactly like an edit is what let a release
            # review report "no deletion entry or absence marker for any removed
            # component" while the range removed six files. The reviewer cannot
            # ask what a deletion cost if the listing never says one happened.
            suffix = "  (DELETED — judge what depended on it)" if path in deleted_paths else ""
            lines.append(f"- {path}{suffix}")
        if deleted_paths:
            substrate = f"ref `{changed_ref}`" if changed_ref else "working tree"
            lines.append("")
            lines.append(
                f"{len(deleted_paths)} of {len(changed_paths)} changed path(s) were DELETED in the "
                f"{substrate}. Their pre-image bytes are bound in the reviewed-input identity, so "
                "what was removed is recoverable."
            )
    elif changed_ref:
        lines.append("- (none — changed ref produced no changed paths)")
    else:
        lines.append("- (none — clean working tree)")
    lines.append("")
    return lines


def _render_owners(payload: dict[str, object]) -> list[str]:
    lines = ["Owning surfaces:"]
    matched = payload["matched_surfaces"]
    if matched:
        for surface in matched:
            lines.append(f"- {surface['surface_id']}: {surface['description']}")
            if surface["matched_source_paths"]:
                lines.append(
                    f"  source matches: {', '.join(surface['matched_source_paths'])}"
                )
            if surface["matched_derived_paths"]:
                lines.append(
                    f"  derived matches: {', '.join(surface['matched_derived_paths'])}"
                )
            if surface["sync_commands"]:
                lines.append(f"  sync: {', '.join(surface['sync_commands'])}")
            if surface["verify_commands"]:
                lines.append(f"  verify: {', '.join(surface['verify_commands'])}")
    else:
        lines.append("- (no surfaces matched the changed paths)")
    lines.append("")
    return lines


def _render_sync(payload: dict[str, object]) -> list[str]:
    sync_commands = payload["sync_commands"]
    if sync_commands:
        lines = ["Planned sync commands before validators:"]
        lines.extend(f"- {command}" for command in sync_commands)
        return lines
    return []


def _render(payload: dict[str, object]) -> str:
    lines = _render_paths(payload)
    lines.extend(_render_owners(payload))
    lines.extend(_render_sync(payload))
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo-root", type=Path, default=REPO_ROOT)
    parser.add_argument(
        "--changed-ref",
        default=os.environ.get("CHARNESS_CRITIQUE_CHANGED_REF")
        or os.environ.get("CHARNESS_RETRO_CHANGED_REF"),
        help="Git commit or range to render instead of the current working tree.",
    )
    args = parser.parse_args()
    repo_root = args.repo_root.resolve()
    try:
        surfaces = load_surfaces(repo_root)
        if args.changed_ref:
            changed_paths, deleted_paths = collect_changed_and_deleted_paths_for_ref(
                repo_root, args.changed_ref
            )
        else:
            snapshot = collect_working_tree_snapshot(repo_root)
            changed_paths = list(snapshot.changed_paths)
            deleted_paths = set(snapshot.deleted_paths)
        declared = _declared_review_paths()
        if declared is not None:
            changed_paths = declared
            deleted_paths &= set(declared)
        match = match_surfaces(surfaces, changed_paths)
    except SurfaceError as exc:
        print(f"surfaces lookup failed: {exc}")
        return 1
    payload = {
        "changed_ref": args.changed_ref,
        "changed_paths": match["changed_paths"],
        "deleted_paths": sorted(deleted_paths),
        "matched_surfaces": match["matched_surfaces"],
        "sync_commands": match["sync_commands"],
        "narrowed": _declared_review_paths() is not None,
    }
    print(_render(payload))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Own short-lived Charness scratch roots and reclaim only what they own.

The process environment already routes ordinary tool caches to the external
runtime key.  This module gives directory-producing carriers one stronger
contract: a per-run root, an owner receipt, an active lock, and a lifecycle
that can be inspected without scanning or guessing about ``/tmp``.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
import shutil
import sys
import tempfile
import time
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any


def _load_repo_runtime_bootstrap():
    pathlib, sys = __import__("pathlib"), __import__("sys")
    marker = ("scripts", "adapter_lib.py")
    parents = pathlib.Path(__file__).resolve().parents
    root = next((p for p in parents if p.joinpath(*marker).is_file()), None)
    if root is not None and str(root) not in sys.path:
        sys.path.insert(0, str(root))


_load_repo_runtime_bootstrap()

try:
    import fcntl
except ImportError:  # pragma: no cover - Windows has no fcntl
    fcntl = None

try:
    from scripts.runtime_bootstrap import import_repo_module, runtime_root
except ModuleNotFoundError:  # direct ``python scripts/runtime_scratch.py``
    _root = Path(__file__).resolve().parent.parent
    if str(_root) not in sys.path:
        sys.path.insert(0, str(_root))
    from scripts.runtime_bootstrap import import_repo_module, runtime_root

_guard = import_repo_module(__file__, "scripts.core.subprocess_guard")
run_process = _guard.run_process


SCHEMA = "charness.runtime-scratch-owner/v1"
SCRATCH_DIR_NAME = "scratch"
OWNER_RECEIPT_NAME = ".charness-owner.json"
OWNER_LOCK_NAME = ".charness-owner.lock"
DEFAULT_RETENTION_SECONDS = 24 * 60 * 60
RETENTION_CLASSES = frozenset({"scratch", "retained-evidence"})
TERMINAL_STATES = frozenset({"succeeded", "failed", "cancelled", "timed-out", "retained"})
_RECEIPT_CORE_FIELDS = frozenset(
    {
        "schema",
        "owner",
        "producer",
        "repo_root",
        "repo_identity",
        "run_id",
        "pid",
        "created_at",
        "updated_at",
        "state",
        "retention",
        "expires_at",
    }
)
_TOKEN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$")


class ScratchError(RuntimeError):
    """Raised when an owner boundary cannot be established safely."""


def _utc_now() -> datetime:
    return datetime.now(timezone.utc)


def _iso(value: datetime) -> str:
    return value.astimezone(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")


def _token(value: str, *, label: str) -> str:
    if not isinstance(value, str) or not _TOKEN.fullmatch(value):
        raise ScratchError(f"{label} must be a simple owner token: {value!r}")
    return value


def _repo_identity(repo_root: Path) -> str:
    return hashlib.sha256(str(repo_root.resolve()).encode("utf-8")).hexdigest()[:16]


def _write_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=path.parent)
    temporary_path = Path(temporary)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(payload, handle, ensure_ascii=False, indent=2, sort_keys=True)
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary_path, path)
    finally:
        temporary_path.unlink(missing_ok=True)


def _read_owner(path: Path) -> dict[str, Any] | None:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    return payload if isinstance(payload, dict) else None


def _tree_inventory(root: Path, *, max_entries: int) -> tuple[int, int, bool]:
    entries = 0
    size = 0
    truncated = False
    stack = [root]
    while stack:
        current = stack.pop()
        try:
            children = list(os.scandir(current))
        except OSError:
            continue
        for entry in children:
            entries += 1
            if entries > max_entries:
                return entries, size, True
            try:
                if entry.is_symlink():
                    continue
                if entry.is_dir(follow_symlinks=False):
                    stack.append(Path(entry.path))
                elif entry.is_file(follow_symlinks=False):
                    size += entry.stat(follow_symlinks=False).st_size
            except OSError:
                truncated = True
    return entries, size, truncated


def _lock_is_active(lock_path: Path) -> bool:
    if not lock_path.is_file():
        return False
    try:
        handle = lock_path.open("a+")
    except OSError:
        return True
    try:
        if fcntl is None:
            return False
        try:
            fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except (BlockingIOError, OSError):
            return True
        fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
        return False
    finally:
        handle.close()


def _pid_is_alive(value: object) -> bool:
    if not isinstance(value, int) or value <= 0:
        return False
    try:
        os.kill(value, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return False
    return True


def _registered_worktrees(repo_root: Path) -> list[Path]:
    try:
        result = run_process(
            ["git", "worktree", "list", "--porcelain"],
            cwd=repo_root,
            timeout_seconds=10,
        )
    except OSError as exc:
        raise ScratchError(f"cannot inspect registered worktrees: {exc}") from exc
    if result.returncode != 0:
        detail = result.stderr.strip() or result.stdout.strip() or "git worktree list failed"
        raise ScratchError(f"cannot inspect registered worktrees: {detail}")
    paths: list[Path] = []
    for line in result.stdout.splitlines():
        if line.startswith("worktree "):
            paths.append(Path(line.removeprefix("worktree ")).resolve())
    return paths


def _contains_path(parent: Path, child: Path) -> bool:
    try:
        child.resolve().relative_to(parent.resolve())
    except ValueError:
        return False
    return True


def _rmtree_writable(path: Path) -> None:
    """Remove owned trees even when a read-only worker input was materialized."""
    for parent, dirs, files in os.walk(path):
        for name in (*dirs, *files):
            target = os.path.join(parent, name)
            if not os.path.islink(target):
                os.chmod(target, 0o700 if os.path.isdir(target) else 0o600)
        os.chmod(parent, 0o700)
    shutil.rmtree(path)


class OwnedScratch:
    """A single producer/run directory with a receipt and a held owner lock."""

    def __init__(
        self,
        repo_root: str | Path,
        producer: str,
        *,
        run_id: str | None = None,
        retention: str = "scratch",
        runtime_root_path: str | Path | None = None,
        retention_seconds: int = DEFAULT_RETENTION_SECONDS,
    ) -> None:
        self.repo_root = Path(repo_root).expanduser().resolve()
        self.producer = _token(producer, label="producer")
        self.run_id = _token(run_id or f"{os.getpid()}-{time.time_ns()}", label="run_id")
        if retention not in RETENTION_CLASSES:
            raise ScratchError(f"unknown retention class: {retention!r}")
        if retention_seconds <= 0:
            raise ScratchError("retention_seconds must be positive")
        base = (
            Path(runtime_root_path).expanduser().resolve()
            if runtime_root_path is not None
            else runtime_root(self.repo_root)
        )
        self.runtime_root = base
        self.path = base / SCRATCH_DIR_NAME / self.producer / self.run_id
        self.receipt_path = self.path / OWNER_RECEIPT_NAME
        self.lock_path = self.path / OWNER_LOCK_NAME
        self.retention = retention
        self.retention_seconds = retention_seconds
        self._lock: Any = None
        self._retained = retention == "retained-evidence"
        self._promoted = False
        self._opened = False

    def _receipt(self, *, state: str, **extra: Any) -> dict[str, Any]:
        now = _utc_now()
        payload: dict[str, Any] = {
            "schema": SCHEMA,
            "owner": "charness",
            "producer": self.producer,
            "repo_root": str(self.repo_root),
            "repo_identity": _repo_identity(self.repo_root),
            "run_id": self.run_id,
            "pid": os.getpid(),
            "created_at": getattr(self, "created_at", now),
            "updated_at": _iso(now),
            "state": state,
            "retention": self.retention,
            "expires_at": _iso(now + timedelta(seconds=self.retention_seconds)),
        }
        payload.update(extra)
        return payload

    def _receipt_preserving(self, *, state: str, **extra: Any) -> dict[str, Any]:
        """Change lifecycle fields without dropping recovery metadata.

        Recovery commands, packet identities, and promotion diagnostics are
        written before owner close.  Rebuilding a terminal receipt from only
        the fixed owner fields used to erase those fields at the exact point
        where retained evidence became useful to a retry.
        """
        existing = _read_owner(self.receipt_path) or {}
        preserved = {
            key: value
            for key, value in existing.items()
            if key not in _RECEIPT_CORE_FIELDS
        }
        preserved.update(extra)
        return self._receipt(state=state, **preserved)

    def open(self) -> Path:
        if self._opened:
            return self.path
        if self.path.exists():
            raise ScratchError(f"scratch run already exists: {self.path}")
        self.path.mkdir(parents=True)
        self.created_at = _iso(_utc_now())
        try:
            self._lock = self.lock_path.open("a+")
            if fcntl is not None:
                fcntl.flock(self._lock.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
            self._lock.write(f"pid={os.getpid()}\n")
            self._lock.flush()
            _write_json(self.receipt_path, self._receipt(state="active"))
        except BaseException as exc:
            # Establishing an owner is one transaction.  If the first receipt
            # write fails, leave a typed retained receipt so the bytes remain
            # inspectable and retryable; do not strand an unreceipted root.
            self._retained = True
            self.retention = "retained-evidence"
            try:
                _write_json(
                    self.receipt_path,
                    self._receipt(state="failed", owner_open_error=str(exc)),
                )
            except BaseException:
                # No caller can safely identify this root without a receipt,
                # and open() has not returned a payload path yet.  Remove only
                # this empty, newly-created owner root rather than leaving an
                # unknown directory for GC to guess about.
                self._close_lock()
                self._opened = False
                shutil.rmtree(self.path, ignore_errors=True)
                raise
            self._opened = True
            self._close_lock()
            raise
        self._opened = True
        return self.path

    def __enter__(self) -> Path:
        return self.open()

    def retain(self) -> None:
        if not self._opened:
            raise ScratchError("cannot retain a scratch root before it is opened")
        self._retained = True
        self.retention = "retained-evidence"
        _write_json(self.receipt_path, self._receipt_preserving(state="retained"))

    def retain_with(self, **extra: Any) -> None:
        """Retain a failed run with the identity needed for a later recovery."""
        if not self._opened:
            raise ScratchError("cannot retain a scratch root before it is opened")
        self._retained = True
        self.retention = "retained-evidence"
        _write_json(self.receipt_path, self._receipt_preserving(state="retained", **extra))

    def retain_failed_promotion(self, **extra: Any) -> None:
        """Keep the source when a caller cannot verify durable promotion."""
        self._promoted = False
        self.retain_with(**extra)

    def update(self, **extra: Any) -> None:
        """Persist active-run metadata needed for crash recovery."""
        if not self._opened:
            raise ScratchError("cannot update a scratch root before it is opened")
        _write_json(self.receipt_path, self._receipt_preserving(state="active", **extra))

    def reopen_existing(self) -> Path:
        """Acquire an abandoned retained root for an identity-checked retry."""
        if self._opened:
            return self.path
        owner = _read_owner(self.receipt_path)
        if owner is None or owner.get("schema") != SCHEMA:
            raise ScratchError(f"cannot reopen an unknown scratch owner: {self.path}")
        if owner.get("repo_identity") != _repo_identity(self.repo_root):
            raise ScratchError("refusing to reopen scratch owned by another repository")
        if owner.get("producer") != self.producer or owner.get("run_id") != self.run_id:
            raise ScratchError("refusing to reopen scratch with a different owner identity")
        if owner.get("retention") != "retained-evidence" or owner.get("state") not in {
            "retained",
            # Registry recovery deliberately records an abandoned active owner
            # as failed.  Failed retained evidence is still a supported retry
            # input; treating only the happy-path terminal state as reopenable
            # strands exactly the bytes recovery promised to preserve.
            "failed",
        }:
            raise ScratchError(
                "scratch root is not retained retry evidence: "
                f"state={owner.get('state')!r}, retention={owner.get('retention')!r}"
            )
        if _pid_is_alive(owner.get("pid")):
            raise ScratchError("refusing to reopen scratch while its owner process is alive")
        try:
            self._lock = self.lock_path.open("a+")
            if fcntl is not None:
                fcntl.flock(self._lock.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except (OSError, BlockingIOError) as exc:
            if self._lock is not None:
                self._lock.close()
                self._lock = None
            raise ScratchError(f"refusing to reopen active scratch root: {self.path}") from exc
        self.created_at = owner.get("created_at", _iso(_utc_now()))
        self._retained = True
        self.retention = "retained-evidence"
        self._opened = True
        _write_json(
            self.receipt_path,
            self._receipt_preserving(state="active", recovery_of=owner.get("run_id")),
        )
        return self.path

    def promote_file(self, source: str | Path, destination: str | Path, *, complete: bool = True) -> Path:
        """Promote complete evidence through the cohesive promotion owner."""
        from scripts.runtime_scratch_promotion import promote_file

        return promote_file(self, source, destination, complete=complete)

    def _close_lock(self) -> None:
        if self._lock is None:
            return
        try:
            if fcntl is not None:
                fcntl.flock(self._lock.fileno(), fcntl.LOCK_UN)
        finally:
            self._lock.close()
            self._lock = None

    def close(self, *, state: str = "succeeded", remove_retained: bool = False) -> None:
        if not self._opened:
            return
        if state not in TERMINAL_STATES:
            raise ScratchError(f"invalid terminal scratch state: {state!r}")
        if self._promoted:
            _write_json(self.receipt_path, self._receipt_preserving(state="retained"))
            self._close_lock()
            _rmtree_writable(self.path)
        elif self._retained and not remove_retained:
            _write_json(self.receipt_path, self._receipt_preserving(state="retained"))
            self._close_lock()
        else:
            _write_json(self.receipt_path, self._receipt_preserving(state=state))
            self._close_lock()
            _rmtree_writable(self.path)
        self._opened = False

    def __exit__(self, exc_type: object, exc: object, traceback: object) -> bool:
        self.close(state="failed" if exc_type is not None else "succeeded")
        return False


