_DESCENDANT_CLEANUP_SHELL = (
    'printf "%s\\n" "$$" > "$1"; shift; exec 3<&0; "$@" <&3 & '
    'child=$!; wait "$child"; status=$?; exit "$status"'
)


def _command_with_normal_completion_cleanup(
    command: Sequence[str], configured_env: Mapping[str, str], group_path: Path
) -> Sequence[str]:
    """Keep the task runner's old whole-group cleanup after a clean child exit."""
    if not command:
        return command
    executable = os.fspath(command[0])
    if "/" in executable:
        available = os.access(executable, os.X_OK)
    else:
        available = (
            shutil.which(executable, path=configured_env.get("PATH", os.defpath)) is not None
        )
    if not available:
        # Keep the guard's FileNotFoundError path for a missing Codex executable.
        return command
    return [
        "sh",
        "-c",
        _DESCENDANT_CLEANUP_SHELL,
        "charness-task-run",
        str(group_path),
        *command,
    ]


def _kill_recorded_process_group(group_path: Path) -> None:
    try:
        group_id = int(group_path.read_text(encoding="ascii").strip())
    except (OSError, ValueError):
        return
    try:
        os.killpg(group_id, signal.SIGKILL)
    except ProcessLookupError:
        pass
    finally:
        group_path.unlink(missing_ok=True)


@contextmanager
def _redirect_stdio(stdin_handle, stdout_handle, stderr_handle):  # noqa: ANN001
    saved = [os.dup(fd) for fd in (0, 1, 2)]
    try:
        for fd, handle in zip((0, 1, 2), (stdin_handle, stdout_handle, stderr_handle)):
            os.dup2(handle.fileno(), fd)
        yield
    finally:
        for fd, saved_fd in zip((0, 1, 2), saved):
            os.dup2(saved_fd, fd)
            os.close(saved_fd)


def _execute_codex(
    command: Sequence[str],
    *,
    prompt: str,
    target_path: Path,
    configured_env: Mapping[str, str],
    stdout_log: Path,
    stderr_log: Path,
    timeout_seconds: int,
) -> dict[str, Any]:
    result: dict[str, Any] = {"exit_code": None, "timed_out": False, "interrupted": False}
    group_path = stdout_log.with_suffix(".pgid")
    group_path.unlink(missing_ok=True)

    try:
        with (
            stdout_log.open("w", encoding="utf-8") as stdout_handle,
            stderr_log.open("w", encoding="utf-8") as stderr_handle,
        ):
            with tempfile.TemporaryFile(mode="w+", encoding="utf-8") as prompt_handle:
                prompt_handle.write(prompt)
                prompt_handle.flush()
                prompt_handle.seek(0)
                terminal_stderr = os.fdopen(os.dup(2), "w", buffering=1, closefd=True)
                outcome = None
                try:
                    with _redirect_stdio(prompt_handle, stdout_handle, stderr_handle):
                        outcome = run_monitored_phase(
                            _command_with_normal_completion_cleanup(
                                command, configured_env, group_path
                            ),
                            cwd=target_path,
                            phase="codex",
                            timeout_seconds=timeout_seconds,
                            display=render_display(command),
                            env=dict(configured_env),
                            capture=False,
                            stream=terminal_stderr,
                        )
                except KeyboardInterrupt:
                    result["interrupted"] = True
                finally:
                    terminal_stderr.close()
                    _kill_recorded_process_group(group_path)
                if outcome is not None:
                    result["timed_out"] = outcome.timed_out
                    result["exit_code"] = None if outcome.timed_out else outcome.returncode
    except OSError as exc:
        result["exec_error"] = str(exc)
    return result


_MAX_RESULT_TEXT_BYTES = 1024 * 1024
_REVIEW_SCAN_LIMIT_BYTES = 64 * 1024 * 1024
_BOUNDED_REVIEW_KIND = "charness.bounded_review.v1"


_REVIEWER_CONTRACT: Any | None = None


def _bounded_result_shape(payload: dict[str, Any]) -> str:
    """Load the shared result contract in source and flat plugin checkouts."""
    global _REVIEWER_CONTRACT
    if _REVIEWER_CONTRACT is None:
        here = Path(__file__).resolve()
        candidates = [
            ancestor / "skills" / "shared" / "scripts" / "reviewer_result_contract.py"
            for ancestor in (here.parent, *here.parents)
        ]
        candidates.extend(
            ancestor / "shared" / "scripts" / "reviewer_result_contract.py"
            for ancestor in (here.parent, *here.parents)
        )
        contract_path = next((candidate for candidate in candidates if candidate.is_file()), None)
        if contract_path is None:
            raise ImportError("shared reviewer_result_contract.py is unavailable")
        spec = importlib.util.spec_from_file_location(
            "charness_reviewer_result_contract", contract_path
        )
        if spec is None or spec.loader is None:
            raise ImportError(f"cannot load reviewer result contract: {contract_path}")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        _REVIEWER_CONTRACT = module
    return _REVIEWER_CONTRACT.bounded_result_shape(payload)


def _nested_mappings(value: Any):
    if isinstance(value, dict):
        yield value
        for nested in value.values():
            yield from _nested_mappings(nested)
    elif isinstance(value, list):
        for nested in value:
            yield from _nested_mappings(nested)


def _extract_bounded_review(raw: bytes) -> tuple[dict[str, Any], str] | None:
    """Find a bounded result after noise, pretty-printing, or a large prefix."""
    if len(raw) > _REVIEW_SCAN_LIMIT_BYTES:
        half = _REVIEW_SCAN_LIMIT_BYTES // 2
        raw = raw[:half] + b"\n[Charness bounded-result scan window]\n" + raw[-half:]
    text = raw.decode("utf-8", errors="replace")
    decoder = json.JSONDecoder()
    for index, char in enumerate(text):
        if char not in "[{":
            continue
        try:
            value, _end = decoder.raw_decode(text, index)
        except json.JSONDecodeError:
            continue
        for candidate in _nested_mappings(value):
            if candidate.get("kind") == _BOUNDED_REVIEW_KIND:
                return dict(candidate), "text-json"
    return None


def _reviewer_result_carrier(delivery: Mapping[str, Any]) -> dict[str, Any] | None:
    """Project a task's bounded-review bytes into a reusable, non-approval carrier.

    `task run` owns durable result.json, including failed and timed-out lanes. A
    reviewer result found there is useful for retry and comparison, but task-run
    delivery alone cannot prove the consumer's expected packet identity. Keep the
    result reusable while requiring the review consumer to bind it before approval.
    """
    candidate = delivery.get("reviewer_result")
    source = str(delivery.get("reviewer_result_source") or "raw-log")
    if not isinstance(candidate, Mapping) or candidate.get("kind") != _BOUNDED_REVIEW_KIND:
        candidate = delivery.get("structured")
        source = "structured"
    if not isinstance(candidate, Mapping) or candidate.get("kind") != _BOUNDED_REVIEW_KIND:
        raw_text = delivery.get("text")
        candidate = None
        if isinstance(raw_text, str):
            try:
                parsed = json.loads(raw_text)
            except json.JSONDecodeError:
                parsed = None
            if isinstance(parsed, dict) and parsed.get("kind") == _BOUNDED_REVIEW_KIND:
                candidate = parsed
                source = "text-json"
            if candidate is None:
                extracted = _extract_bounded_review(raw_text.encode("utf-8"))
                if extracted is not None:
                    candidate, source = extracted
    if not isinstance(candidate, Mapping) or candidate.get("kind") != _BOUNDED_REVIEW_KIND:
        return None
    validation = _bounded_result_shape(dict(candidate))
    complete = validation != "partial-schema"
    return {
        "schema_version": "charness.task_reviewer_carrier.v1",
        "state": "received" if complete else "partial",
        "delivery_state": "findings-received" if complete else "partial",
        "reusable": True,
        "approval_eligible": False,
        "identity_binding": "consumer-required",
        "source": source,
        "result_kind": _BOUNDED_REVIEW_KIND,
        # Keep the bounded finding body beside its projection.  `result_delivery`
        # already retains the raw carrier, but callers should not have to parse a
        # log again merely to reuse a failed review as retry context.
        "result": dict(candidate),
        "verdict": candidate.get("verdict"),
        "packet_identity": candidate.get("packet_sha256"),
        "reviewed_input_identity": candidate.get("reviewed_input_identity_sha256"),
        "validation": validation,
        "next_move": (
            "Bind packet/input identity and the task receipt before treating this as approval."
            if complete
            else "Reuse the retained partial result as retry context; do not approve it."
        ),
    }


def _result_delivery(stdout_log: Path) -> dict[str, Any]:
    try:
        raw = stdout_log.read_bytes() if stdout_log.is_file() else b""
    except OSError as exc:
        return {
            "status": "non-delivery",
            "bytes": None,
            "truncated": False,
            "text": "",
            "log": str(stdout_log),
            "structured_status": "unavailable",
            "delivery_error": str(exc),
            "delivery_error_type": type(exc).__name__,
        }
    delivered = bool(raw.strip())
    clipped = raw[:_MAX_RESULT_TEXT_BYTES]
    text = clipped.decode("utf-8", errors="replace")
    result: dict[str, Any] = {
        "status": "delivered" if delivered else "non-delivery",
        "bytes": len(raw),
        "truncated": len(raw) > len(clipped),
        "text": text,
        "log": str(stdout_log),
    }
    result["structured_status"] = "not-applicable"
    extracted = _extract_bounded_review(raw)
    if extracted is not None:
        result["reviewer_result"], result["reviewer_result_source"] = extracted
    if delivered and not result["truncated"]:
        try:
            structured = yaml.safe_load(text)
        except yaml.YAMLError:
            if "schema_version" in text:
                result["structured_status"] = "invalid"
        else:
            if isinstance(structured, Mapping) and "schema_version" in structured:
                try:
                    json.dumps(structured)
                except (TypeError, ValueError):
                    result["structured_status"] = "invalid"
                else:
                    result["structured_status"] = "valid"
                    result["structured"] = dict(structured)
    return result

"""Consumer-side validation for a narrowed critique follow-up packet."""

from __future__ import annotations

import hashlib
from typing import Any


def _path_set_digest(paths: list[str]) -> str:
    return hashlib.sha256("\n".join(sorted(set(paths))).encode("utf-8")).hexdigest()


def _manifest_paths(content: str) -> list[str] | None:
    lines = content.splitlines()
    try:
        start = lines.index("Exact reviewed-path manifest:") + 1
    except ValueError:
        return None
    paths: list[str] = []
    for line in lines[start:]:
        if not line:
            break
        if not line.startswith("- "):
            return None
        value = line[2:].split("  (DELETED", 1)[0]
        if value and not value.startswith("("):
            paths.append(value)
    return paths


def refuse_if_unbound(
    support: Any,
    packet: dict[str, Any],
    reviewed_paths: list[str],
) -> None:
    """Refuse a narrowed packet whose producer scope receipt is unproven."""
    follow_up = packet.get("follow_up")
    if not isinstance(follow_up, dict):
        return
    receipt = packet.get("follow_up_scope")
    if not isinstance(receipt, dict) or receipt.get("status") != "verified":
        raise support.RunReviewError(
            "follow-up-scope-unbound",
            "follow-up packet has no verified producer-scope receipt",
        )
    selected = receipt.get("selected_paths")
    if sorted(selected or []) != sorted(reviewed_paths):
        raise support.RunReviewError(
            "follow-up-scope-mismatch",
            "follow-up producer-scope receipt does not match packet identity paths",
            details={"receipt_paths": selected, "identity_paths": reviewed_paths},
        )
    by_id = {
        item.get("section_id"): item
        for item in receipt.get("sections", [])
        if isinstance(item, dict) and isinstance(item.get("section_id"), str)
    }
    sections = packet.get("sections") if isinstance(packet.get("sections"), list) else []
    expected_ids = {section.get("id") for section in sections if isinstance(section, dict)}
    if set(by_id) != expected_ids or any(item.get("status") != "verified" for item in by_id.values()):
        raise support.RunReviewError(
            "follow-up-scope-unbound",
            "follow-up producer-scope receipt does not cover every packet section",
        )
    for section in sections:
        if not isinstance(section, dict) or by_id[section.get("id")].get("mode") != "selected-paths":
            continue
        receipt_section = by_id[section.get("id")]
        if receipt_section.get("path_binding") != "exact-path-manifest":
            raise support.RunReviewError(
                "follow-up-producer-out-of-scope",
                f"follow-up producer section `{section.get('id')}` has no exact path binding",
            )
        manifest_paths = _manifest_paths(section.get("content") or "")
        actual_paths = sorted(set(manifest_paths or []))
        if actual_paths != sorted(set(reviewed_paths)):
            raise support.RunReviewError(
                "follow-up-producer-out-of-scope",
                f"follow-up producer section `{section.get('id')}` path manifest is not exact",
                details={"expected_paths": reviewed_paths, "actual_paths": actual_paths},
            )
        if receipt_section.get("path_set_sha256") != _path_set_digest(reviewed_paths):
            raise support.RunReviewError(
                "follow-up-scope-mismatch",
                f"follow-up producer section `{section.get('id')}` path digest does not match",
            )

"""Bound and bind the inert context carried by a critique follow-up."""

from __future__ import annotations

import hashlib
import json
from typing import Any, Callable

MAX_CONTEXT_BYTES = 24 * 1024
MAX_FINDINGS = 64


def clip(value: object, limit: int) -> str:
    text = value if isinstance(value, str) else json.dumps(value, ensure_ascii=False, sort_keys=True)
    if len(text) <= limit:
        return text
    return text[: max(0, limit - 16)] + "…[truncated]"


def compact_findings(raw: object) -> tuple[list[dict[str, Any]], list[str], bool]:
    if not isinstance(raw, list):
        return [], [], False
    findings: list[dict[str, Any]] = []
    omitted: list[str] = []
    for index, item in enumerate(raw):
        if not isinstance(item, dict):
            continue
        finding_id = item.get("id")
        stable_id = str(finding_id) if finding_id is not None else f"finding-{index + 1}"
        evidence = item.get("evidence")
        evidence_items = evidence if isinstance(evidence, list) else []
        findings.append(
            {
                "id": stable_id,
                "severity": clip(item.get("severity", "unknown"), 80),
                "summary": clip(item.get("summary", ""), 480),
                "action": clip(item.get("action", ""), 640),
                "evidence": [clip(entry, 520) for entry in evidence_items[:4]],
            }
        )
    if len(findings) > MAX_FINDINGS:
        omitted = [str(item.get("id")) for item in findings[MAX_FINDINGS:] if item.get("id")]
        findings = findings[:MAX_FINDINGS]
    return findings, omitted, False


def context_bytes(context: dict[str, Any]) -> bytes:
    return (json.dumps(context, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode(
        "utf-8"
    )


def _path_digest(paths: list[str]) -> str:
    encoded = json.dumps(sorted(set(paths)), ensure_ascii=False, separators=(",", ":")).encode()
    return hashlib.sha256(encoded).hexdigest()


def _collapse_path_arrays(value: object, key: str = "") -> object:
    if isinstance(value, dict):
        return {
            name: (
                {"count": len(nested), "sha256": _path_digest(nested), "summarized": True}
                if name.endswith("paths")
                and isinstance(nested, list)
                and all(isinstance(item, str) for item in nested)
                else _collapse_path_arrays(nested, name)
            )
            for name, nested in value.items()
        }
    if isinstance(value, list) and key.endswith("paths") and all(isinstance(item, str) for item in value):
        return {"count": len(value), "sha256": _path_digest(value), "summarized": True}
    if isinstance(value, list):
        return [_collapse_path_arrays(item, key) for item in value]
    return value


def bound_context(
    context: dict[str, Any], error: Callable[..., Exception]
) -> dict[str, Any]:
    if len(context_bytes(context)) <= MAX_CONTEXT_BYTES:
        return context
    findings = context.get("prior_findings")
    if isinstance(findings, list):
        for finding in findings:
            if isinstance(finding, dict):
                finding["evidence"] = [str(item)[:220] for item in finding.get("evidence", [])[:1]]
                finding["action"] = clip(finding.get("action", ""), 300)
                finding["summary"] = clip(finding.get("summary", ""), 300)
    context["context_truncated"] = True
    if len(context_bytes(context)) <= MAX_CONTEXT_BYTES:
        return context
    context["prior_findings"] = [
        {key: value for key, value in finding.items() if key in {"id", "severity", "summary"}}
        for finding in findings or []
        if isinstance(finding, dict)
    ]
    for key in ("selected_paths", "prior_reviewed_paths", "comparison", "selection_receipt"):
        if key in context:
            context[key] = _collapse_path_arrays(context[key], key)
    if len(context_bytes(context)) <= MAX_CONTEXT_BYTES:
        return context
    context = {
        key: context[key]
        for key in (
            "kind",
            "source",
            "source_sha256",
            "prior_attempt_id",
            "prior_verdict",
            "prior_packet_path",
            "prior_packet_sha256",
            "prior_reviewed_input_identity_sha256",
            "selection",
            "selected_paths",
            "selection_receipt",
            "prior_findings",
            "approval_rule",
            "context_truncated",
        )
        if key in context
    }
    context["prior_findings"] = [
        {key: finding.get(key, "") for key in ("id", "severity", "summary")}
        for finding in context.get("prior_findings", [])
        if isinstance(finding, dict)
    ]
    context["selected_paths"] = _collapse_path_arrays(context.get("selected_paths", []), "selected_paths")
    context["selection_receipt"] = _collapse_path_arrays(
        context.get("selection_receipt", {}), "selection_receipt"
    )
    findings = context.get("prior_findings")
    if isinstance(findings, list):
        original_count = len(findings)
        for summary_limit in (160, 80, 40, 0):
            context["prior_findings"] = [
                {
                    "id": finding.get("id", ""),
                    "severity": finding.get("severity", ""),
                    "summary": clip(finding.get("summary", ""), summary_limit),
                }
                for finding in findings
                if isinstance(finding, dict)
            ]
            if len(context_bytes(context)) <= MAX_CONTEXT_BYTES:
                return context
        retained = context["prior_findings"]
        while retained and len(context_bytes(context)) > MAX_CONTEXT_BYTES:
            retained.pop()
        omitted = original_count - len(retained)
        if omitted:
            context["prior_findings_omitted"] = omitted
    if len(context_bytes(context)) > MAX_CONTEXT_BYTES:
        raise error(
            "follow-up-context-too-large",
            "follow-up context cannot be reduced under its hard byte bound",
            details={"size_bytes": len(context_bytes(context)), "max_bytes": MAX_CONTEXT_BYTES},
        )
    return context


def bind_final_identity(
    context: dict[str, Any], identity: dict[str, Any], error: Callable[..., Exception]
) -> dict[str, Any]:
    """Join selection context to the identity of the packet actually assembled."""
    context["final_reviewed_input_identity_sha256"] = identity.get("identity_sha256")
    context["final_selected_path_count"] = len(identity.get("reviewed_paths", []))
    context.pop("context_size_bytes", None)
    context["context_size_bytes"] = 0
    for _ in range(8):
        size = len(context_bytes(context))
        if context["context_size_bytes"] == size:
            break
        context["context_size_bytes"] = size
    final_size = len(context_bytes(context))
    if final_size > MAX_CONTEXT_BYTES or context["context_size_bytes"] != final_size:
        raise error(
            "follow-up-context-too-large",
            "final follow-up context exceeds its hard byte bound",
            details={"size_bytes": final_size, "max_bytes": MAX_CONTEXT_BYTES},
        )
    return context

"""Bind reusable follow-up findings to their retained reviewer attempt."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Callable


def _retained_source(root: Path, value: object) -> Path | None:
    if not isinstance(value, str) or not value:
        return None
    candidate = Path(value)
    if candidate.is_absolute() or ".." in candidate.parts:
        return None
    lexical = root / candidate
    if lexical.is_symlink() or not lexical.is_file():
        return None
    try:
        lexical.resolve().relative_to(root.resolve())
    except ValueError:
        return None
    return lexical


def _json_objects(raw: bytes) -> list[dict[str, Any]]:
    text = raw.decode("utf-8", errors="replace")
    decoder = json.JSONDecoder()
    objects: list[dict[str, Any]] = []
    for index, char in enumerate(text):
        if char != "{":
            continue
        try:
            value, _end = decoder.raw_decode(text, index)
        except json.JSONDecodeError:
            continue
        if isinstance(value, dict):
            objects.append(value)
    return objects


def _source_contains_result(source: Path, raw: dict[str, Any]) -> bool:
    """Prove the selected partial result was emitted by its retained log."""
    return any(candidate == raw for candidate in _json_objects(source.read_bytes()))


def verify_result_carrier(  # noqa: C901, PLR0915
    *,
    root: Path,
    source: Path,
    raw: dict[str, Any],
    plan: dict[str, Any],
    identity: dict[str, Any],
    load_mapping: Callable[[Path], dict[str, Any]],
    sha256: Callable[[Path], str],
    error: Callable[..., Exception],
) -> dict[str, Any]:
    """Bind reusable findings to the retained attempt that owns the packet."""
    run_dir = source.parent
    manifest_path = run_dir / "attempt-manifest.json"
    receipt_path = run_dir / "receipt.json"
    delivery_path = run_dir / "delivery.json"
    report_path = run_dir / "worker-report.yaml"
    result_path = run_dir / "result.json"
    required = (manifest_path, receipt_path, delivery_path, report_path)
    if any(not path.is_file() or path.is_symlink() for path in required):
        raise error(
            "prior-result-unbound",
            "prior result is missing the retained attempt provenance chain",
        )

    manifest = load_mapping(manifest_path)
    receipt = load_mapping(receipt_path)
    delivery = load_mapping(delivery_path)
    report = load_mapping(report_path)
    result = load_mapping(result_path) if result_path.is_file() and not result_path.is_symlink() else None
    attempt = manifest.get("attempt_id")
    if not isinstance(attempt, str) or not attempt:
        raise error("prior-result-unbound", "retained attempt manifest has no attempt_id")
    packet_sha = plan.get("packet_sha256")
    input_sha = plan.get("reviewed_input_identity_sha256")
    if not isinstance(packet_sha, str) or not isinstance(input_sha, str):
        raise error("prior-result-unbound", "retained run plan has no packet/input identities")
    if identity.get("identity_sha256") != input_sha:
        raise error("prior-result-unbound", "retained packet identity is not bound to the run plan")
    if raw.get("packet_sha256") != packet_sha or raw.get("reviewed_input_identity_sha256") != input_sha:
        raise error(
            "prior-result-unbound",
            "prior result carrier identities do not match the retained run plan",
        )

    identity_pairs = (
        ("attempt_id", attempt),
        ("packet_identity", packet_sha),
        ("reviewed_input_identity", input_sha),
    )
    for name, expected in identity_pairs:
        actuals = {
            "manifest": manifest.get(name),
            "receipt": receipt.get(name),
            "report": report.get(name),
            "result": result.get(name) if isinstance(result, dict) else None,
            "plan": plan.get(name),
        }
        if name == "attempt_id" and actuals["result"] is None:
            actuals.pop("result")
        if any(value is not None and value != expected for value in actuals.values()):
            raise error(
                "prior-result-unbound",
                f"retained prior result `{name}` identity does not match the attempt",
                details={"expected": expected, "actual": actuals},
            )

    descriptor = manifest.get("partial_result")
    partial_relative = source.relative_to(root).as_posix()
    source_digest = sha256(source)
    manifest_files = manifest.get("files")
    if not isinstance(descriptor, dict) or descriptor.get("path") != partial_relative:
        raise error(
            "prior-result-unbound",
            "prior result is not the partial-result carrier recorded by its attempt manifest",
        )
    if descriptor.get("sha256") != source_digest or descriptor.get("bytes") != source.stat().st_size:
        raise error(
            "prior-result-tampered",
            "prior result bytes do not match the retained attempt descriptor",
        )
    if not isinstance(manifest_files, dict) or manifest_files.get("partial-result.json") != partial_relative:
        raise error(
            "prior-result-unbound",
            "retained attempt manifest does not expose the supplied result carrier",
        )
    source_path = _retained_source(root, descriptor.get("source"))
    source_relative_value = descriptor.get("source")
    if source_path is None or not isinstance(source_relative_value, str):
        raise error(
            "prior-result-unbound",
            "prior result has no safe retained backend source",
        )
    backend_relative = source_path.relative_to(root).as_posix()
    if backend_relative != source_relative_value:
        raise error("prior-result-unbound", "prior backend source path is not repository-relative")
    if backend_relative not in {
        value for value in manifest_files.values() if isinstance(value, str)
    }:
        raise error(
            "prior-result-unbound",
            "prior result backend source is not exposed by the attempt manifest",
        )
    logs = manifest.get("logs")
    log_descriptor = next(
        (
            value
            for value in logs.values()
            if isinstance(value, dict) and value.get("path") == backend_relative
        ),
        None,
    ) if isinstance(logs, dict) else None
    if not isinstance(log_descriptor, dict):
        raise error("prior-result-unbound", "prior backend source has no retained log descriptor")
    retained_bytes = source_path.stat().st_size
    expected_bytes = log_descriptor.get("retained_bytes") if log_descriptor.get("truncated") else log_descriptor.get("bytes")
    if expected_bytes != retained_bytes:
        raise error("prior-result-tampered", "retained backend source byte count changed")
    if not log_descriptor.get("truncated") and log_descriptor.get("sha256") != sha256(source_path):
        raise error("prior-result-tampered", "retained backend source digest changed")
    if not _source_contains_result(source_path, raw):
        raise error(
            "prior-result-tampered",
            "partial result is not present in its retained backend source",
        )
    if isinstance(result, dict):
        if not all(result.get(key) == value for key, value in raw.items()):
            raise error(
                "prior-result-unbound",
                "partial result is not a projection of the receipt-bound result carrier",
            )
    else:
        retained_partial = receipt.get("retained_partial_output")
        if not isinstance(retained_partial, dict):
            raise error(
                "prior-result-unbound",
                "partial-only result has no receipt-bound retained descriptor",
            )
        if (
            retained_partial.get("path") != partial_relative
            or retained_partial.get("bytes") != source.stat().st_size
            or retained_partial.get("sha256") != source_digest
        ):
            raise error(
                "prior-result-tampered",
                "partial-only result does not match the receipt-bound retained descriptor",
            )
    if report.get("receipt_path") != receipt_path.relative_to(root).as_posix():
        raise error("prior-result-unbound", "prior report receipt path is not retained")
    if report.get("ledger_path") != delivery_path.relative_to(root).as_posix():
        raise error("prior-result-unbound", "prior report delivery path is not retained")
    producer = report.get("producer_binding")
    producer_output = producer.get("output_file") if isinstance(producer, dict) else None
    receipt_output = receipt.get("output_file")
    if not isinstance(producer, dict):
        raise error(
            "prior-result-unbound",
            "prior report is not bound to its result file",
            details={
                "producer_output_file": producer_output,
                "expected_output_file": result_path.relative_to(root).as_posix(),
                "result_present": isinstance(result, dict),
            },
        )
    if isinstance(result, dict):
        if producer_output != result_path.relative_to(root).as_posix() or receipt_output != result_path.relative_to(root).as_posix():
            raise error(
                "prior-result-unbound",
                "prior report is not bound to its result file",
                details={
                    "producer_output_file": producer_output,
                    "receipt_output_file": receipt_output,
                    "expected_output_file": result_path.relative_to(root).as_posix(),
                    "result_present": True,
                },
            )
    elif producer_output != receipt_output or not isinstance(producer_output, str) or Path(producer_output).name != "result.json":
        raise error(
            "prior-result-unbound",
            "partial-only report and receipt do not share the producer output binding",
            details={
                "producer_output_file": producer_output,
                "receipt_output_file": receipt_output,
                "result_present": False,
            },
        )

    result_digest = sha256(result_path) if isinstance(result, dict) else None
    if isinstance(result, dict) and (
        receipt.get("output_sha256") != result_digest
        or report.get("receipt_output_sha256") != result_digest
    ):
        raise error("prior-result-unbound", "prior result digest is not bound by receipt/report")
    attempts = delivery.get("attempts") if isinstance(delivery, dict) else None
    delivery_attempt = next(
        (item for item in attempts or [] if isinstance(item, dict) and item.get("attempt_id") == attempt),
        None,
    )
    if not isinstance(delivery_attempt, dict) or any(
        delivery_attempt.get(key) != expected
        for key, expected in (
            ("packet_identity", packet_sha),
            ("reviewed_input_identity", input_sha),
            ("parent_receipt_identity", plan.get("parent_receipt_identity")),
        )
    ):
        raise error("prior-result-unbound", "prior delivery ledger does not bind the result attempt")
    return {
        "status": "verified",
        "attempt_id": attempt,
        "partial_result_sha256": source_digest,
        "result_sha256": result_digest,
        "source_path": backend_relative,
    }

"""Select an identity-bound follow-up path set from a prior packet."""

from __future__ import annotations

from pathlib import Path
from typing import Any, Callable


def _content_index(identity: dict[str, Any]) -> dict[str, tuple[object, object]]:
    entries = identity.get("reviewed_content")
    if not isinstance(entries, list):
        return {}
    return {
        item["path"]: (item.get("content_sha256"), item.get("disposition"))
        for item in entries
        if isinstance(item, dict) and isinstance(item.get("path"), str)
    }


def select_paths(
    *,
    repo_root: Path,
    identity: dict[str, Any],
    prior_paths: list[str],
    explicit_paths: list[str] | None,
    prior_mode: str | None,
    current_mode: str,
    changed_ref: str | None,
    build_identity: Callable[..., dict[str, Any]],
    prior_binding: dict[str, Any],
    error: Callable[..., Exception],
) -> tuple[list[str], str, dict[str, Any] | None, dict[str, Any]]:
    """Return paths, selection label, comparison, and a selection receipt."""
    comparison: dict[str, Any] | None = None
    receipt: dict[str, Any] = {
        "prior_binding": prior_binding,
        "explicit_paths": bool(explicit_paths),
    }
    if explicit_paths:
        paths = sorted(set(explicit_paths))
        selection = "explicit-with-selection-receipt"
        comparable = prior_mode == current_mode and prior_paths and isinstance(
            identity.get("reviewed_content"), list
        )
        if comparable:
            prior_ref = identity.get("changed_ref") or identity.get("resolved_changed_ref")
            if current_mode == "committed-ref" and changed_ref != prior_ref:
                receipt["rationale"] = (
                    "Explicit paths were supplied because the committed review ref differs "
                    "from the prior ref; selection is not approval."
                )
                comparison = {
                    "prior_paths": len(prior_paths),
                    "changed_prior_paths": [],
                    "selected_changed_prior_paths": [],
                    "new_paths": sorted(set(paths) - set(prior_paths)),
                    "unchanged_selected_paths": [],
                    "omitted_changed_prior_paths": [],
                    "comparison_ref": {"prior": prior_ref, "current": changed_ref},
                }
            else:
                try:
                    current = build_identity(
                        repo_root=repo_root,
                        reviewed_paths=prior_paths,
                        changed_ref=changed_ref,
                        substrate_mode=current_mode,
                    )
                except (KeyError, TypeError, ValueError) as exc:
                    raise error("follow-up-delta-unavailable", str(exc)) from exc
                if current.get("status") != "captured":
                    raise error(
                        "follow-up-delta-unavailable",
                        "current review identity could not be captured for explicit selection",
                        details={"identity": current},
                    )
                before = _content_index(identity)
                after = _content_index(current)
                changed_prior = sorted(
                    path for path in prior_paths if before.get(path) != after.get(path)
                )
                selected = set(paths)
                prior = set(prior_paths)
                new_paths = sorted(selected - prior)
                unchanged = sorted(path for path in selected & prior if path not in changed_prior)
                omitted = sorted(set(changed_prior) - selected)
                comparison = {
                    "prior_paths": len(prior_paths),
                    "changed_prior_paths": changed_prior,
                    "selected_changed_prior_paths": sorted(set(changed_prior) & selected),
                    "new_paths": new_paths,
                    "unchanged_selected_paths": unchanged,
                    "omitted_changed_prior_paths": omitted,
                    "comparison_identity_sha256": current.get("identity_sha256"),
                    "comparison_identity_paths": sorted(prior),
                }
                receipt.update(
                    {
                        "prior_identity_sha256": identity.get("identity_sha256"),
                        "comparison_identity_sha256": current.get("identity_sha256"),
                        "comparison_identity_paths": sorted(prior),
                        "selected_changed_prior_paths": sorted(set(changed_prior) & selected),
                        "new_paths": new_paths,
                        "unchanged_selected_paths": unchanged,
                        "omitted_changed_prior_paths": omitted,
                        "rationale": (
                            "Explicit paths were supplied to include newly introduced consumers "
                            "or intentionally widen the stimulus; selection is not approval."
                        ),
                    }
                )
        elif prior_mode not in {None, current_mode}:
            raise error(
                "follow-up-substrate-mismatch",
                "explicit follow-up paths cannot silently compare different review substrates",
                details={"prior_substrate_mode": prior_mode, "current_substrate_mode": current_mode},
            )
        else:
            receipt["rationale"] = (
                "Explicit paths were supplied because the prior packet does not expose a "
                "comparable working-tree path identity; selection is not approval."
            )
        return paths, selection, comparison, receipt

    if prior_mode != current_mode:
        raise error(
            "follow-up-paths-required",
            "a follow-up cannot derive a delta from a different review substrate; provide --reviewed-path",
            details={
                "prior_substrate_mode": prior_mode,
                "current_substrate_mode": current_mode,
                "prior_paths": prior_paths,
            },
        )
    if not prior_paths or not isinstance(identity.get("reviewed_content"), list):
        raise error(
            "follow-up-paths-required",
            "prior review has no reconstructable reviewed paths; provide --reviewed-path",
        )
    if current_mode == "committed-ref":
        prior_ref = identity.get("changed_ref") or identity.get("resolved_changed_ref")
        if changed_ref != prior_ref:
            raise error(
                "follow-up-ref-mismatch",
                "implicit committed-ref follow-up requires the same pinned ref",
                details={"prior_ref": prior_ref, "current_ref": changed_ref},
            )
    try:
        current = build_identity(
            repo_root=repo_root,
            reviewed_paths=prior_paths,
            changed_ref=changed_ref,
            substrate_mode=current_mode,
        )
    except (KeyError, TypeError, ValueError) as exc:
        raise error("follow-up-delta-unavailable", str(exc)) from exc
    if current.get("status") != "captured":
        raise error(
            "follow-up-delta-unavailable",
            "current working-tree identity could not be captured; provide explicit paths",
            details={"identity": current},
        )
    before = _content_index(identity)
    after = _content_index(current)
    paths = sorted(path for path in prior_paths if before.get(path) != after.get(path))
    comparison = {
        "prior_paths": len(prior_paths),
        "changed_paths": len(paths),
        "comparison_identity_sha256": current.get("identity_sha256"),
        "comparison_identity_paths": sorted(prior_paths),
    }
    receipt.update(
        {
            "prior_identity_sha256": identity.get("identity_sha256"),
            "comparison_identity_sha256": current.get("identity_sha256"),
            "comparison_identity_paths": sorted(prior_paths),
            "selected_changed_prior_paths": paths,
            "new_paths": [],
            "unchanged_selected_paths": [],
            "omitted_changed_prior_paths": [],
        }
    )
    if not paths:
        raise error(
            "follow-up-no-delta",
            "no previously reviewed input changed; provide --reviewed-path for a new stimulus",
            details=comparison,
        )
    return paths, "changed-prior-inputs", comparison, receipt

"""Lifecycle and durable-path handling for one critique review carrier."""

from __future__ import annotations

from pathlib import Path
from typing import Any

import yaml


def refresh_manifest_integrity(
    support: Any, storage: Any, root: Path, manifest_relative: str
) -> dict[str, Any]:
    """Hash every promoted file after the final lifecycle bytes are written."""
    manifest = support.repo_path(
        root, manifest_relative, label="promoted attempt manifest", require_file=True
    )
    payload = support.load_mapping(manifest)
    if not isinstance(payload, dict):
        raise support.RunReviewError(
            "promotion-readback-failed", "promoted attempt manifest is not a mapping"
        )
    files = payload.get("files")
    if not isinstance(files, dict):
        raise support.RunReviewError(
            "promotion-readback-failed", "promoted attempt manifest has no file map"
        )
    integrity: dict[str, dict[str, Any]] = {}
    for name, relative in sorted(files.items()):
        if not isinstance(name, str) or not isinstance(relative, str):
            raise support.RunReviewError(
                "promotion-readback-failed", "promoted attempt manifest contains a malformed file"
            )
        path = support.repo_path(root, relative, label=f"promoted file {name}", require_file=True)
        integrity[name] = {
            "path": relative,
            "bytes": path.stat().st_size,
            "sha256": support.sha256(path),
        }
    payload["file_integrity"] = integrity
    storage.write_json_atomically(manifest, payload)
    readback = support.load_mapping(manifest)
    if not isinstance(readback, dict) or readback.get("file_integrity") != integrity:
        raise support.RunReviewError(
            "promotion-readback-failed", "promoted attempt manifest integrity did not read back"
        )
    return integrity


def write_promoted_yaml(
    support: Any, storage: Any, root: Path, relative_path: str, payload: dict[str, Any]
) -> None:
    """Atomically rewrite a promoted lifecycle carrier after path rebinding."""
    lexical_destination = root / relative_path
    if lexical_destination.is_symlink():
        raise support.RunReviewError(
            "stale-artifact-refused",
            f"refusing to write through lifecycle symlink: {lexical_destination}",
        )
    destination = lexical_destination.resolve()
    try:
        destination.relative_to(root.resolve())
    except ValueError as exc:
        raise support.RunReviewError(
            "path-invalid", "promoted lifecycle path escaped repository root"
        ) from exc
    encoded = yaml.safe_dump(payload, allow_unicode=True, sort_keys=False).encode("utf-8")
    storage.write_bytes_atomically(destination, encoded)


def compare_report_stream(support: Any, stream_path: Path, report_path: Path) -> dict[str, Any]:
    """Record whether stdout and the durable report carry the same mapping."""
    stream = support.load_mapping(stream_path)
    report = support.load_mapping(report_path)
    if stream is None or report is None:
        reason = "runner stdout or canonical report is missing or unreadable"
        consistent = False
    elif stream != report:
        reason = "runner stdout differs from the canonical report carrier"
        consistent = False
    else:
        reason = None
        consistent = True
    return {
        "consistent": consistent,
        "reason": reason,
        "runner_stdout_sha256": support.sha256(stream_path) if stream_path.is_file() else None,
        "canonical_report_sha256": support.sha256(report_path) if report_path.is_file() else None,
    }


def failure_carrier(
    packet_module: Any,
    lifecycle: Any,
    *,
    scope: str,
    lens: str,
    error: str,
    code: str,
    details: dict[str, Any],
) -> dict[str, Any]:
    if lifecycle is None:
        return {
            "schema_version": "charness.reviewer_lifecycle.v1",
            "status": "runner-invalid",
            "execution_state": "preflight-blocked",
            "lifecycle_state": "preflight-blocked",
            "reviewer_started": False,
            "delivery_state": "none",
            "verdict_state": "not-applicable",
            "review_verdict": None,
            "classification": None,
            "approval_eligible": False,
            "output": {"state": "none", "approval_eligible": False, "artifacts": []},
            "output_state": "none",
            "failure_identity": None,
            "next_move": "repair the named preflight boundary and rerun; reviewer did not start",
            "runner_returncode": None,
            "runner_status": "runner-invalid",
            "boundary_ok": None,
            "boundary_reason": None,
            "paths": {},
        }
    carrier = lifecycle.build_lifecycle(
        status="runner-invalid", error=error, reviewer_started=False, paths={}
    )
    carrier.update(
        {
            "ok": False,
            "carrier_ok": False,
            "reason_code": code,
            "error": error,
            "details": details,
            "scope": scope,
            "lens": lens,
        }
    )
    for field in packet_module.REFUSAL_DETAIL_FIELDS:
        if field in details:
            carrier[field] = details[field]
    return carrier


def bind_promoted_paths(context: dict[str, Any], promoted: dict[str, str], promotion: Any) -> dict[str, str]:
    """Replace runtime-only paths with their durable receipt paths."""
    bound = context.setdefault("paths", {})
    old_paths = dict(bound)
    for name, relative in promoted.items():
        source_key = promotion.SOURCE_KEYS.get(name)
        if source_key is not None:
            bound[source_key] = relative
    worker_report = promoted.get("worker-report.yaml")
    if worker_report is not None:
        runtime_report = old_paths.get("report")
        if runtime_report is not None and runtime_report != worker_report:
            bound["runtime_report"] = runtime_report
        bound["report"] = worker_report
        bound["durable_report"] = worker_report
    for name, source_key in promotion.LOG_SOURCE_KEYS.items():
        relative = promoted.get(name)
        if relative is not None:
            bound[source_key] = relative
    for key, value in list(bound.items()):
        if isinstance(value, str) and Path(value).parts[:2] == (".charness", "scratch"):
            bound.pop(key, None)
    return bound


def rebind_partial_artifacts(
    carrier: dict[str, Any], old_paths: dict[str, str], new_paths: dict[str, str], promotion: Any
) -> None:
    """Keep lifecycle partial-output descriptors usable after scratch cleanup."""
    collections = [carrier.get("partial_outputs")]
    output = carrier.get("output")
    if isinstance(output, dict):
        collections.extend((output.get("artifacts"), output.get("partial_artifacts")))
    for collection in collections:
        if not isinstance(collection, list):
            continue
        for descriptor in collection:
            if not isinstance(descriptor, dict):
                continue
            path = descriptor.get("path")
            if not isinstance(path, str):
                continue
            for key in promotion.LOG_SOURCE_KEYS.values():
                if path == old_paths.get(key) and key in new_paths:
                    descriptor["path"] = new_paths[key]
                    break


def replace_exact_strings(value: Any, replacements: dict[str, str]) -> Any:
    if isinstance(value, dict):
        for key, nested in list(value.items()):
            value[key] = replace_exact_strings(nested, replacements)
        return value
    if isinstance(value, list):
        return [replace_exact_strings(item, replacements) for item in value]
    if isinstance(value, str):
        return replacements.get(value, value)
    return value


def finalize_carrier(
    support: Any,
    promotion: Any,
    root: Path,
    promotion_attempt: str,
    paths: dict[str, Path],
    context: dict[str, Any],
    carrier: dict[str, Any],
    report: dict[str, Any] | None,
    recovery_validation: dict[str, Any] | None = None,
) -> None:
    """Promote all terminal bytes, then emit paths that survive owner cleanup."""
    old_paths = dict(context.setdefault("paths", {}))
    promoted = promotion.promote_attempt_metadata(
        root,
        promotion_attempt,
        paths,
        report,
        finalize=True,
        expected_identities={
            "packet_sha256": context.get("packet_sha256"),
            "reviewed_input_identity_sha256": context.get("reviewed_input_identity_sha256"),
            "parent_receipt_identity": context.get("parent_receipt_identity"),
        },
        final_carrier=carrier,
        recovery_validation=recovery_validation,
    )
    semantic_replacements: dict[str, str] = {}
    run_dir = paths.get("run_dir")
    source_dir = run_dir / "semantic-input" if run_dir is not None else None
    if source_dir is not None and source_dir.is_dir():
        for source in source_dir.rglob("*"):
            if not source.is_file() or source.is_symlink():
                continue
            relative = source.relative_to(source_dir)
            promoted_key = f"semantic-input/{relative.as_posix()}"
            durable = promoted.get(promoted_key)
            if durable is not None:
                semantic_replacements[support.relative(root, source)] = durable
    if semantic_replacements:
        carrier["semantic_input"] = replace_exact_strings(
            carrier.get("semantic_input"), semantic_replacements
        )
    bound = bind_promoted_paths(context, promoted, promotion)
    rebind_partial_artifacts(carrier, old_paths, bound, promotion)
    carrier["paths"] = dict(bound)
    summary = promoted.get("lifecycle.yaml")
    if summary is not None:
        write_promoted_yaml(support, promotion.STORAGE, root, summary, carrier)
        saved_summary = support.load_mapping(root / summary)
        if not isinstance(saved_summary, dict):
            raise support.RunReviewError(
                "promotion-readback-failed",
                "promoted lifecycle carrier could not be read back as a mapping",
            )
        for key in (
            "schema_version",
            "execution_state",
            "lifecycle_state",
            "delivery_state",
            "approval_eligible",
            "identity_check",
            "runner_stream",
        ):
            if key in carrier and saved_summary.get(key) != carrier.get(key):
                raise support.RunReviewError(
                    "promotion-readback-failed",
                    f"promoted lifecycle carrier changed at `{key}` during read-back",
                )
    manifest_path = promoted.get("attempt-manifest.json")
    if manifest_path is not None:
        promotion.refresh_manifest_integrity(root, manifest_path)
    manifest = support.load_mapping(root / manifest_path) if manifest_path else None
    if not isinstance(manifest, dict):
        raise support.RunReviewError(
            "promotion-readback-failed",
            "promoted reviewer attempt manifest could not be read back",
        )
    expected_approval = carrier.get("approval_eligible") is True
    if manifest.get("approval_eligible") is not expected_approval:
        raise support.RunReviewError(
            "promotion-readback-failed",
            "promoted reviewer manifest approval does not match the final lifecycle carrier",
        )


def owner_terminal_state(status: str, carrier: dict[str, Any]) -> str:
    """Map reviewer execution state to the scratch owner's explicit terminal state."""
    delivery = carrier.get("delivery_state")
    if status == "runner-timeout" or delivery == "timed-out":
        return "timed-out"
    if status == "runner-interrupted" or delivery == "interrupted":
        return "cancelled"
    if carrier.get("execution_state") == "terminal" and delivery == "findings-received":
        return "succeeded"
    return "failed"

"""Atomic storage helpers for durable critique-review carriers."""

from __future__ import annotations

import hashlib
import importlib.util
import json
import os
import shutil
import sys
import tempfile
from pathlib import Path
from typing import Any

DURABLE_WORKER_REPORTS = Path("charness-artifacts") / "critique" / "workers"
PROMOTED_METADATA = (
    "worker-report.yaml",
    "review-prompt.md",
    "run-plan.json",
    "bounded-review-result.schema.json",
    "capability.json",
    "lifecycle.yaml",
    "receipt.json",
    "delivery.json",
    "result.json",
)
SOURCE_KEYS = {
    "review-prompt.md": "prompt",
    "run-plan.json": "plan",
    "bounded-review-result.schema.json": "schema",
    "capability.json": "capability",
    "lifecycle.yaml": "summary",
    "receipt.json": "receipt",
    "delivery.json": "ledger",
    "result.json": "output",
}
# A reviewer can emit diagnostics before its final JSON.  Scan a bounded
# head/tail window rather than assuming the result is an early one-line record.
# The durable typed result is still much smaller than the log cap below.
PARTIAL_SCAN_LIMIT = 64 * 1024 * 1024
MAX_DURABLE_LOG_BYTES = 4 * 1024 * 1024
LOG_SOURCE_KEYS = {
    "runner.stdout": "runner_stdout",
    "runner.stderr": "runner_stderr",
    "backend.stdout": "backend_stdout",
    "backend.stderr": "backend_stderr",
}


def _support() -> Any:
    for name in ("charness_run_review_support", "run_review_support"):
        module = sys.modules.get(name)
        if module is not None:
            return module
    path = Path(__file__).with_name("run_review_support.py")
    spec = importlib.util.spec_from_file_location("charness_run_review_support", path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"cannot load run_review_support: {path}")
    module = importlib.util.module_from_spec(spec)
    sys.modules["charness_run_review_support"] = module
    spec.loader.exec_module(module)
    return module


_REVIEWER_CONTRACT: Any | None = None


def _bounded_result_shape(payload: dict[str, Any]) -> str:
    """Load the shared result contract in both source and flat plugin layouts."""
    global _REVIEWER_CONTRACT
    if _REVIEWER_CONTRACT is None:
        here = Path(__file__).resolve()
        candidates = [
            ancestor / "skills" / "shared" / "scripts" / "reviewer_result_contract.py"
            for ancestor in (here.parent, *here.parents)
        ]
        candidates.extend(
            ancestor / "shared" / "scripts" / "reviewer_result_contract.py"
            for ancestor in (here.parent, *here.parents)
        )
        contract_path = next((candidate for candidate in candidates if candidate.is_file()), None)
        if contract_path is None:
            raise ImportError("shared reviewer_result_contract.py is unavailable")
        spec = importlib.util.spec_from_file_location(
            "charness_reviewer_result_contract", contract_path
        )
        if spec is None or spec.loader is None:
            raise ImportError(f"cannot load reviewer result contract: {contract_path}")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        _REVIEWER_CONTRACT = module
    return _REVIEWER_CONTRACT.bounded_result_shape(payload)


def _copy_atomically(source: Path, destination: Path) -> None:
    """Copy a bounded carrier without exposing a half-written durable file."""
    fd, temporary = tempfile.mkstemp(
        prefix=f".{destination.name}.", suffix=".tmp", dir=destination.parent
    )
    temporary_path = Path(temporary)
    try:
        with source.open("rb") as source_handle, os.fdopen(fd, "wb") as destination_handle:
            shutil.copyfileobj(source_handle, destination_handle)
            destination_handle.flush()
            os.fsync(destination_handle.fileno())
        os.replace(temporary_path, destination)
    finally:
        temporary_path.unlink(missing_ok=True)


def copy_or_verify(source: Path, destination: Path) -> None:
    """Copy a durable input, or accept an identical prior promotion."""
    write_or_verify(destination, source.read_bytes())


def write_or_verify(destination: Path, payload: bytes) -> None:
    """Write durable bytes once, or accept an identical prior promotion."""
    if destination.is_symlink():
        raise _support().RunReviewError(
            "stale-artifact-refused",
            f"refusing to overwrite durable reviewer metadata: {destination}",
        )
    if destination.exists():
        if not destination.is_file() or destination.read_bytes() != payload:
            raise _support().RunReviewError(
                "stale-artifact-refused",
                f"refusing to overwrite durable reviewer metadata: {destination}",
            )
        return
    destination.parent.mkdir(parents=True, exist_ok=True)
    write_bytes_atomically(destination, payload)


def promote_worker_report(root: Path, attempt: str, runtime_report: Path) -> Path | None:
    """Copy the combined report into visible knowledge for older callers."""
    if not runtime_report.is_file():
        return None
    lexical_dest_dir = root / DURABLE_WORKER_REPORTS / attempt
    if lexical_dest_dir.is_symlink():
        raise _support().RunReviewError(
            "stale-artifact-refused",
            f"refusing to write through durable worker directory symlink: {lexical_dest_dir}",
        )
    dest_dir = lexical_dest_dir.resolve()
    try:
        dest_dir.relative_to(root.resolve())
    except ValueError as exc:
        raise _support().RunReviewError(
            "path-invalid", "durable worker report directory escaped repository root"
        ) from exc
    dest_dir.mkdir(parents=True, exist_ok=True)
    dest = dest_dir / "worker-report.yaml"
    if dest.exists() or dest.is_symlink():
        raise _support().RunReviewError(
            "stale-artifact-refused",
            f"refusing to overwrite existing durable worker report: {dest}",
        )
    _copy_atomically(runtime_report, dest)
    return dest


def promote_semantic_inputs(
    root: Path, paths: dict[str, Path], dest_dir: Path
) -> dict[str, str]:
    """Retain backend-independent semantic bytes after scratch cleanup."""
    run_dir = paths.get("run_dir")
    source_dir = run_dir / "semantic-input" if run_dir is not None else None
    if source_dir is None or not source_dir.is_dir():
        return {}
    promoted: dict[str, str] = {}
    for source in sorted(source_dir.rglob("*")):
        if not source.is_file() or source.is_symlink():
            continue
        relative = source.relative_to(source_dir)
        destination = dest_dir / "semantic-input" / relative
        payload = source.read_bytes()
        if relative.as_posix() == "manifest.json":
            replacements = {
                _support().relative(root, source_dir / Path(key.removeprefix("semantic-input/"))): value
                for key, value in promoted.items()
                if key.startswith("semantic-input/") and key != "semantic-input/manifest.json"
            }
            payload = rewrite_path_references(payload, replacements)
        write_or_verify(destination, payload)
        source_mode = source.stat().st_mode & 0o777
        if destination.stat().st_mode & 0o777 != source_mode:
            if destination.exists() and destination.read_bytes() == payload:
                destination.chmod(source_mode)
            else:
                raise _support().RunReviewError(
                    "stale-artifact-refused",
                    f"durable semantic input mode changed: {destination}",
                )
        promoted[f"semantic-input/{relative.as_posix()}"] = _support().relative(root, destination)
    return promoted


def rewrite_path_references(payload: bytes, replacements: dict[str, str]) -> bytes:
    rewritten = payload
    for old, new in sorted(replacements.items(), key=lambda item: len(item[0]), reverse=True):
        rewritten = rewritten.replace(old.encode("utf-8"), new.encode("utf-8"))
    return rewritten


def report_path_replacements(
    paths: dict[str, Path], promoted: dict[str, str]
) -> dict[str, str]:
    """Rebind worker-report references from scratch bytes to durable carriers."""
    replacements: dict[str, str] = {}
    for name, source_key in SOURCE_KEYS.items():
        source = paths.get(source_key)
        durable = promoted.get(name)
        if source is not None and durable is not None:
            replacements[str(source)] = durable
    report_source = paths.get("report")
    durable_report = promoted.get("worker-report.yaml")
    if report_source is not None and durable_report is not None:
        replacements[str(report_source)] = durable_report
    return replacements


def semantic_path_replacements(
    root: Path, paths: dict[str, Path], promoted: dict[str, str]
) -> dict[str, str]:
    """Map materialized semantic-input paths to their durable copies."""
    run_dir = paths.get("run_dir")
    source_dir = run_dir / "semantic-input" if run_dir is not None else None
    if source_dir is None or not source_dir.is_dir():
        return {}
    replacements: dict[str, str] = {}
    for source in source_dir.rglob("*"):
        if not source.is_file() or source.is_symlink():
            continue
        relative = source.relative_to(source_dir)
        promoted_key = f"semantic-input/{relative.as_posix()}"
        durable = promoted.get(promoted_key)
        if durable is not None:
            replacements[_support().relative(root, source)] = durable
    return replacements


def write_json_atomically(destination: Path, payload: object) -> None:
    fd, temporary = tempfile.mkstemp(
        prefix=f".{destination.name}.", suffix=".tmp", dir=destination.parent
    )
    temporary_path = Path(temporary)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(payload, handle, ensure_ascii=False, indent=2, sort_keys=True)
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary_path, destination)
    finally:
        temporary_path.unlink(missing_ok=True)


def write_bytes_atomically(destination: Path, payload: bytes) -> None:
    fd, temporary = tempfile.mkstemp(
        prefix=f".{destination.name}.", suffix=".tmp", dir=destination.parent
    )
    temporary_path = Path(temporary)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary_path, destination)
    finally:
        temporary_path.unlink(missing_ok=True)


def promote_log(root: Path, source: Path, destination: Path) -> dict[str, Any]:
    raw = source.read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    retained = raw
    truncated = False
    if len(raw) > MAX_DURABLE_LOG_BYTES:
        half = (MAX_DURABLE_LOG_BYTES - 96) // 2
        marker = b"\n[Charness durable log truncated; see source hash in manifest]\n"
        retained = raw[:half] + marker + raw[-half:]
        truncated = True
    if destination.is_symlink():
        raise _support().RunReviewError(
            "stale-artifact-refused",
            f"refusing to overwrite durable reviewer log: {destination}",
        )
    if destination.exists():
        if not destination.is_file() or destination.read_bytes() != retained:
            raise _support().RunReviewError(
                "stale-artifact-refused",
                f"refusing to overwrite durable reviewer log: {destination}",
            )
    else:
        write_bytes_atomically(destination, retained)
    return {
        "path": _support().relative(root, destination),
        "source": _support().relative(root, source),
        "bytes": len(raw),
        "retained_bytes": len(retained),
        "sha256": digest,
        "truncated": truncated,
    }


def _nested_dicts(value: Any):
    if isinstance(value, dict):
        yield value
        for nested in value.values():
            yield from _nested_dicts(nested)
    elif isinstance(value, list):
        for nested in value:
            yield from _nested_dicts(nested)


def _json_values(raw: bytes):
    """Yield JSON values from noisy, line-delimited, or pretty-printed output."""
    if len(raw) > PARTIAL_SCAN_LIMIT:
        half = PARTIAL_SCAN_LIMIT // 2
        raw = raw[:half] + b"\n[Charness partial scan window]\n" + raw[-half:]
    text = raw.decode("utf-8", errors="replace")
    decoder = json.JSONDecoder()
    for index, char in enumerate(text):
        if char not in "[{":
            continue
        try:
            value, _end = decoder.raw_decode(text, index)
        except json.JSONDecodeError:
            continue
        yield from _nested_dicts(value)


def extract_partial_review(
    paths: dict[str, Path],
    report: dict[str, Any] | None,
    diagnostics: dict[str, Any] | None = None,
    *,
    expected_identities: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], Path, str] | None:
    """Find a matching bounded-review object in preserved runner logs.

    The result may be late, pretty-printed, wrapped by a backend envelope, or
    interleaved with ordinary log text.  Identity matching remains mandatory.
    """
    info = diagnostics if diagnostics is not None else {}
    info.update({"status": "unavailable", "scan_limit_bytes": PARTIAL_SCAN_LIMIT, "sources": []})
    expected = expected_identities or {}
    expected_packet = (
        expected.get("packet_sha256")
        or (report.get("packet_identity") if report else None)
        or (report.get("packet_sha256") if report else None)
    )
    expected_input = (
        expected.get("reviewed_input_identity_sha256")
        or (report.get("reviewed_input_identity") if report else None)
        or (report.get("reviewed_input_identity_sha256") if report else None)
    )
    expected_parent = expected.get("parent_receipt_identity") or (
        report.get("parent_receipt_identity") if report else None
    )
    if expected_packet is None or expected_input is None:
        info["reason"] = "worker report has no packet and reviewed-input identities"
        return None
    for key in LOG_SOURCE_KEYS:
        source = paths.get(LOG_SOURCE_KEYS[key])
        if source is None or not source.is_file():
            continue
        try:
            raw = source.read_bytes()
        except OSError:
            continue
        info["sources"].append(
            {
                "key": key,
                "path": str(source),
                "bytes": len(raw),
                "scanned_bytes": min(len(raw), PARTIAL_SCAN_LIMIT),
                "windowed": len(raw) > PARTIAL_SCAN_LIMIT,
            }
        )
        for candidate in _json_values(raw):
            if not isinstance(candidate, dict) or candidate.get("kind") != "charness.bounded_review.v1":
                continue
            if candidate.get("packet_sha256") != expected_packet:
                continue
            if candidate.get("reviewed_input_identity_sha256") != expected_input:
                continue
            if (
                expected_parent is not None
                and candidate.get("parent_receipt_identity") not in {None, expected_parent}
            ):
                continue
            validation = _bounded_result_shape(candidate)
            info.update({"status": "preserved", "reason": "matching identity-bound JSON found"})
            return candidate, source, validation
    info["reason"] = "no identity-matching bounded-review object was found in the bounded log windows"
    return None

"""Validate the immutable inputs of a retained critique reviewer attempt."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any


def parent_receipt_identity(plan: dict[str, Any]) -> str:
    unsigned = dict(plan)
    unsigned.pop("parent_receipt_identity", None)
    encoded = (json.dumps(unsigned, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode()
    return "parent-" + hashlib.sha256(encoded).hexdigest()[:48]


def non_approval_carrier(reason: str) -> dict[str, Any]:
    return {
        "approval_eligible": False,
        "identity_check": {"matches": False, "reason": reason},
        "runner_stream": {"consistent": False, "reason": reason},
    }


def validate_retained_inputs(  # noqa: C901, PLR0915
    root: Path,
    plan: dict[str, Any],
    packet: Path,
    paths: dict[str, Path],
    *,
    attempt: str,
    owner_receipt: Path,
    package: dict[str, Path],
    support: Any,
    packet_module: Any,
    identity_verification: Any,
) -> dict[str, Any]:
    """Rebind retained bytes before allowing a recovery carrier to approve."""
    checks: dict[str, Any] = {}

    def invalid(reason: str, **details: Any) -> dict[str, Any]:
        return {"status": "invalid", "ok": False, "reason": reason, "checks": checks, **details}

    if plan.get("attempt_id") != attempt:
        return invalid(
            "retained run plan attempt_id does not match the requested attempt",
            expected_attempt=attempt,
            actual_attempt=plan.get("attempt_id"),
        )
    owner = support.load_mapping(owner_receipt)
    if not isinstance(owner, dict):
        return invalid("retained owner receipt is missing or unreadable")
    checks["owner_receipt"] = {
        "attempt_id": {"expected": attempt, "actual": owner.get("attempt_id")},
        "packet_identity": {
            "expected": plan.get("packet_sha256"),
            "actual": owner.get("packet_identity"),
        },
        "reviewed_input_identity": {
            "expected": plan.get("reviewed_input_identity_sha256"),
            "actual": owner.get("reviewed_input_identity"),
        },
        "parent_receipt_identity": {
            "expected": plan.get("parent_receipt_identity"),
            "actual": owner.get("parent_receipt_identity"),
        },
    }
    if any(
        (
            owner.get("attempt_id") != attempt,
            owner.get("packet_identity") != plan.get("packet_sha256"),
            owner.get("reviewed_input_identity") != plan.get("reviewed_input_identity_sha256"),
            owner.get("parent_receipt_identity") != plan.get("parent_receipt_identity"),
        )
    ):
        return invalid("retained owner receipt does not bind the requested attempt")
    actual_plan = support.sha256(paths["plan"]) if paths["plan"].is_file() else None
    checks["plan_sha256"] = {"expected": owner.get("plan_sha256"), "actual": actual_plan}
    if not isinstance(owner.get("plan_sha256"), str) or owner.get("plan_sha256") != actual_plan:
        return invalid("retained run plan bytes do not match the owner receipt")

    retained_paths = {
        "receipt": "receipt",
        "delivery": "ledger",
        "result": "output",
        "report": "report",
        "summary": "summary",
    }
    for label, key in retained_paths.items():
        path = paths.get(key)
        actual = support.sha256(path) if path is not None and path.is_file() else None
        expected = owner.get(f"{label}_sha256")
        checks[f"{label}_sha256"] = {"expected": expected, "actual": actual}
        if not isinstance(expected, str) or actual != expected:
            return invalid(f"retained {label} bytes do not match the owner receipt")

    worker_receipt = support.load_mapping(paths["receipt"])
    if not isinstance(worker_receipt, dict):
        return invalid("retained worker receipt is missing or unreadable")
    for field, expected in (
        ("attempt_id", attempt),
        ("packet_identity", plan.get("packet_sha256")),
        ("reviewed_input_identity", plan.get("reviewed_input_identity_sha256")),
        ("parent_receipt_identity", plan.get("parent_receipt_identity")),
    ):
        if worker_receipt.get(field) != expected:
            return invalid(f"retained worker receipt {field} does not match the run plan")
    delivery = support.load_mapping(paths["ledger"])
    attempts = delivery.get("attempts") if isinstance(delivery, dict) else None
    delivery_attempt = next(
        (item for item in attempts or [] if isinstance(item, dict) and item.get("attempt_id") == attempt),
        None,
    )
    if not isinstance(delivery_attempt, dict):
        return invalid("retained delivery ledger has no requested attempt")
    for field, expected in (
        ("packet_identity", plan.get("packet_sha256")),
        ("reviewed_input_identity", plan.get("reviewed_input_identity_sha256")),
        ("parent_receipt_identity", plan.get("parent_receipt_identity")),
    ):
        if delivery_attempt.get(field) != expected:
            return invalid(f"retained delivery ledger {field} does not match the run plan")
    checks["delivery_chain"] = {
        "status": "verified",
        "attempt_id": attempt,
        "state": delivery_attempt.get("state"),
    }

    expected_packet = plan.get("packet_sha256")
    actual_packet = support.sha256(packet) if packet.is_file() else None
    checks["packet_sha256"] = {"expected": expected_packet, "actual": actual_packet}
    if not isinstance(expected_packet, str) or actual_packet != expected_packet:
        return invalid("retained packet bytes do not match the run plan")
    packet_payload = support.load_mapping(packet)
    if not isinstance(packet_payload, dict):
        return invalid("retained packet is not a mapping")
    try:
        packet_module.read_packet(
            support,
            root,
            support.relative(root, packet),
            package["verify_packet"],
        )
    except (support.RunReviewError, OSError, ValueError) as exc:
        return invalid(f"canonical retained packet verification failed: {exc}")
    packet_identity = packet_payload.get("reviewed_input_identity")
    if not isinstance(packet_identity, dict):
        return invalid("retained packet has no reviewed input identity")
    expected_input = plan.get("reviewed_input_identity_sha256")
    actual_input = packet_identity.get("identity_sha256")
    checks["reviewed_input_identity_sha256"] = {"expected": expected_input, "actual": actual_input}
    if not isinstance(expected_input, str) or actual_input != expected_input:
        return invalid("retained packet identity does not match the run plan")
    expected_parent = plan.get("parent_receipt_identity")
    actual_parent = parent_receipt_identity(plan)
    checks["parent_receipt_identity"] = {"expected": expected_parent, "actual": actual_parent}
    if not isinstance(expected_parent, str) or actual_parent != expected_parent:
        return invalid("retained parent receipt identity does not match the run plan")

    manifest_path = paths["run_dir"] / "semantic-input" / "manifest.json"
    if not manifest_path.is_file() or manifest_path.is_symlink():
        return invalid("retained semantic-input manifest is missing")
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return invalid("retained semantic-input manifest is unreadable")
    entries = manifest.get("entries") if isinstance(manifest, dict) else None
    expected_content = {
        item.get("path"): item.get("content_sha256")
        for item in packet_identity.get("reviewed_content", [])
        if isinstance(item, dict) and isinstance(item.get("path"), str)
    }
    if not isinstance(entries, list) or {item.get("path") for item in entries if isinstance(item, dict)} != set(expected_content):
        return invalid("retained semantic-input manifest paths do not match the packet")
    semantic_root = manifest_path.parent.resolve()
    for entry in entries:
        if not isinstance(entry, dict):
            return invalid("retained semantic-input manifest contains a malformed entry")
        value = entry.get("carrier_path")
        if not isinstance(value, str) or not isinstance(entry.get("path"), str):
            return invalid("retained semantic-input manifest entry has no carrier path")
        try:
            carrier = support.repo_path(root, value, label="retained semantic carrier", require_file=True)
            carrier.resolve().relative_to(semantic_root)
        except (support.RunReviewError, ValueError):
            return invalid("retained semantic carrier escaped its run")
        expected = expected_content.get(entry["path"])
        if entry.get("content_sha256") != expected:
            return invalid("retained semantic carrier manifest does not match the packet", path=entry["path"])
        verified, reason = identity_verification.verify_semantic_carrier_entry(
            packet_identity, entry, carrier.read_bytes()
        )
        if not verified:
            return invalid(
                "retained semantic carrier bytes do not match the packet",
                path=entry["path"],
                expected=expected,
                reason=reason,
            )
    checks["semantic_input"] = {"status": "verified", "entries": len(entries)}
    return {"status": "verified", "ok": True, "checks": checks}


def validate_promoted_chain(
    root: Path,
    paths: dict[str, str],
    final_carrier: dict[str, Any],
    expected: dict[str, Any],
    *,
    support: Any,
    carrier_validation: Any,
    promotion: Any,
) -> dict[str, Any]:
    """Reopen every durable carrier before recovery removes retained bytes."""
    required = {"report", "receipt", "ledger", "output", "summary"}
    if not required.issubset(paths):
        return {
            "status": "invalid",
            "ok": False,
            "reason": "promoted chain did not expose every durable carrier",
        }
    durable = {
        key: support.repo_path(root, paths[key], label=f"promoted {key}", require_file=True)
        for key in required
    }
    report = support.load_mapping(durable["report"])
    try:
        carrier_validation.validate_delivered_worker_report(
            repo_root=root,
            report=report,
            expected_attempt_id=expected["attempt_id"],
            expected_paths={
                "receipt": durable["receipt"],
                "delivery": durable["ledger"],
                "result": durable["output"],
            },
        )
    except (ValueError, OSError, KeyError) as exc:
        return {
            "status": "invalid",
            "ok": False,
            "reason": f"promoted worker chain validation failed: {exc}",
        }
    binding = promotion.identity_binding(report, expected)
    lifecycle = support.load_mapping(durable["summary"])
    manifest_path = durable["summary"].with_name("attempt-manifest.json")
    manifest = support.load_mapping(manifest_path)
    files = manifest.get("files") if isinstance(manifest, dict) else None
    integrity = manifest.get("file_integrity") if isinstance(manifest, dict) else None
    if not isinstance(files, dict) or not isinstance(integrity, dict):
        return {
            "status": "invalid",
            "ok": False,
            "reason": "promoted attempt manifest has no complete file-integrity map",
        }
    if set(files) != set(integrity):
        return {
            "status": "invalid",
            "ok": False,
            "reason": "promoted attempt manifest file-integrity keys do not match its files",
        }
    for name, relative in files.items():
        descriptor = integrity.get(name)
        if not isinstance(relative, str) or not isinstance(descriptor, dict):
            return {
                "status": "invalid",
                "ok": False,
                "reason": f"promoted file-integrity descriptor is malformed for {name}",
            }
        try:
            file_path = support.repo_path(
                root, relative, label=f"promoted file {name}", require_file=True
            )
        except (support.RunReviewError, OSError, ValueError) as exc:
            return {
                "status": "invalid",
                "ok": False,
                "reason": f"promoted file-integrity path is invalid for {name}: {exc}",
            }
        if (
            descriptor.get("path") != relative
            or descriptor.get("bytes") != file_path.stat().st_size
            or descriptor.get("sha256") != support.sha256(file_path)
        ):
            return {
                "status": "invalid",
                "ok": False,
                "reason": f"promoted file-integrity check failed for {name}",
            }
    if lifecycle != final_carrier:
        return {
            "status": "invalid",
            "ok": False,
            "reason": "promoted lifecycle carrier does not match the reconstructed final carrier",
        }
    if binding.get("matches") is not True:
        return {
            "status": "invalid",
            "ok": False,
            "reason": "promoted worker report identity does not match the requested attempt",
            "identity_binding": binding,
        }
    expected_approval = final_carrier.get("approval_eligible") is True
    if manifest.get("approval_eligible") is not expected_approval:
        return {
            "status": "invalid",
            "ok": False,
            "reason": "promoted attempt manifest disagrees with the final lifecycle carrier",
        }
    return {
        "status": "verified",
        "ok": True,
        "durable_paths": {key: support.relative(root, value) for key, value in durable.items()},
        "attempt_manifest": support.relative(root, manifest_path),
        "identity_binding": binding,
        "file_integrity": {"status": "verified", "files": len(files)},
    }

#!/usr/bin/env python3
"""Support functions for the semantic critique review command."""

from __future__ import annotations

import hashlib
import importlib.util
import json
import os
import re
import shutil
import signal
import sys
from datetime import datetime
from pathlib import Path
from typing import Any

import yaml

try:
    from scripts.core.subprocess_guard import run_monitored_phase, run_process
    from scripts.runtime_scratch import owned_scratch
except ModuleNotFoundError:
    _scripts_dir = next(
        (
            ancestor / "scripts"
            for ancestor in (Path(__file__).resolve(), *Path(__file__).resolve().parents)
            if (ancestor / "scripts" / "core" / "subprocess_guard.py").is_file()
        ),
        None,
    )
    if _scripts_dir is None:
        raise
    sys.path.insert(0, str(_scripts_dir.parent))  # the repo root: `scripts` is a package
    from scripts.core.subprocess_guard import run_monitored_phase, run_process
    from scripts.runtime_scratch import owned_scratch


class RunReviewError(ValueError):
    """A typed refusal before or during the convenience boundary."""

    def __init__(self, code: str, message: str, *, details: dict[str, Any] | None = None) -> None:
        super().__init__(message)
        self.code = code
        self.details = details or {}


def find_shared_scripts(script_dir: Path) -> Path:
    """Locate the source or installed-plugin shared reviewer scripts."""
    for ancestor in (script_dir, *script_dir.parents):
        for candidate in (ancestor / "shared/scripts", ancestor / "skills/shared/scripts"):
            if (candidate / "run_reviewer_worker.py").is_file():
                return candidate
    raise RunReviewError("runtime-unavailable", "cannot locate Charness shared reviewer scripts")


def find_reviewed_input_verification(script_dir: Path) -> Path:
    """Locate the verifier shipped with the active source or plugin surface."""
    for ancestor in (script_dir, *script_dir.parents):
        candidate = ancestor / "scripts/review/reviewed_input_verification.py"
        if candidate.is_file():
            return candidate
    raise RunReviewError(
        "runtime-unavailable",
        "cannot locate Charness reviewed-input verification script",
    )


def load_module(path: Path, name: str) -> Any:
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise RunReviewError("runtime-unavailable", f"cannot load package helper: {path}")
    module = importlib.util.module_from_spec(spec)
    previous = sys.modules.get(name)
    sys.modules[name] = module
    try:
        spec.loader.exec_module(module)
    except Exception:
        if previous is None:
            sys.modules.pop(name, None)
        else:
            sys.modules[name] = previous
        raise
    if previous is not None:
        sys.modules[name] = previous
    return module


def package_paths(script_dir: Path) -> dict[str, Path]:
    shared = find_shared_scripts(script_dir)
    identity_verification = find_reviewed_input_verification(script_dir)
    schema_candidates = (
        shared.parent / "references/bounded-review-result.schema.json",
        shared.parent.parent / "shared/references/bounded-review-result.schema.json",
    )
    schema = next((path for path in schema_candidates if path.is_file()), None)
    if schema is None:
        raise RunReviewError(
            "runtime-unavailable", "cannot locate canonical reviewer result schema"
        )
    return {
        "runner": shared / "run_reviewer_worker.py",
        "capability": shared / "reviewer_capability.py",
        "lifecycle": shared / "reviewer_lifecycle.py",
        "partial_output": shared / "reviewer_partial_output.py",
        "schema": schema,
        "prepare": script_dir / "prepare_packet.py",
        "verify_packet": script_dir / "verify_packet.py",
        "resolve_adapter": script_dir / "resolve_adapter.py",
        "carrier_validation": shared / "reviewer_worker_carrier_support.py",
        "identity_verification": identity_verification,
    }


def load_runtime(paths: dict[str, Path]) -> tuple[Any, Any]:
    lifecycle = load_module(paths["lifecycle"], "charness_run_review_lifecycle")
    capability = load_module(paths["capability"], "charness_run_review_capability")
    return lifecycle, capability


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def write_json(path: Path, payload: object) -> None:
    path.write_text(
        json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def write_yaml(path: Path, payload: object) -> None:
    path.write_text(yaml.safe_dump(payload, allow_unicode=True, sort_keys=False), encoding="utf-8")


def emit(payload: dict[str, Any]) -> None:
    print(yaml.safe_dump(payload, allow_unicode=True, sort_keys=False), end="")


def yaml_payload(raw: str, *, label: str) -> dict[str, Any]:
    try:
        payload = yaml.safe_load(raw) if raw.strip() else None
    except yaml.YAMLError as exc:
        raise RunReviewError("carrier-invalid", f"{label} did not emit valid YAML: {exc}") from exc
    if not isinstance(payload, dict):
        raise RunReviewError("carrier-invalid", f"{label} did not emit a YAML mapping")
    return payload


def repo_path(
    root: Path,
    value: str,
    *,
    label: str,
    require_file: bool = False,
    allow_symlink: bool = False,
) -> Path:
    """Resolve a repo-relative path this runner will OPEN, or (with
    `allow_symlink`) one it merely declares.

    The symlink refusal is right for files the runner reads or writes — a packet
    or manifest behind a link could be swapped underneath it. It is wrong for a
    DECLARED reviewed path, whose symlink policy belongs to
    `scripts/review/reviewed_input_identity.py`: that owner binds a current pointer by
    link payload and refuses every other symlink. Applying this rule there made
    the runner refuse inputs the identity had just been taught to bind, which is
    the same two-owners-one-question shape the identity repairs were about.

    The repo-root boundary below still applies either way, and `.resolve()`
    follows the link, so a symlink escaping the root is still refused.
    """
    raw = Path(value).expanduser()
    if raw.is_absolute() or ".." in raw.parts:
        raise RunReviewError("path-invalid", f"{label} must be repository-relative: {value}")
    lexical = root / raw
    if lexical.is_symlink() and not allow_symlink:
        raise RunReviewError("path-invalid", f"{label} must not be a symlink: {value}")
    candidate = lexical.resolve(strict=False)
    try:
        candidate.relative_to(root.resolve())
    except ValueError as exc:
        raise RunReviewError(
            "path-invalid", f"{label} resolves outside --repo-root: {value}"
        ) from exc
    if require_file and not candidate.is_file():
        raise RunReviewError("path-missing", f"{label} does not point to a file: {value}")
    # An allowed symlink is returned UNRESOLVED. `.resolve()` follows the link, so
    # returning `candidate` renamed a declared `latest.md` to whatever record it
    # points at -- and a declared set carrying the target instead of the pointer
    # no longer matches the range that listed the pointer. The resolved form is
    # still what the boundary check above ran against.
    return lexical if lexical.is_symlink() else candidate


def hold_out(root: Path, relative_paths: list[str]) -> Any:
    module = load_module(Path(__file__).with_name("run_review_hold_out.py"), "charness_run_review_hold_out")
    return module.hold_out(
        root, relative_paths, resolve_path=repo_path, error_cls=RunReviewError
    )


def relative(root: Path, path: Path) -> str:
    """Repo-relative spelling of a path, WITHOUT following a symlink.

    `.resolve()` here renamed a declared `latest.md` to whatever record it points
    at, so the declared set carried the target while the range carried the
    pointer and the two could never match. `repo_path` has already proven the
    path lies inside the root, so resolving again buys nothing and costs the
    caller's own name for it.
    """
    absolute = path if path.is_absolute() else root / path
    try:
        return absolute.relative_to(root.resolve()).as_posix()
    except ValueError:
        return absolute.resolve().relative_to(root.resolve()).as_posix()


def load_goal_lineage(root: Path, path_value: str | None, *, reason: str) -> dict[str, Any]:
    """Load one full evidence identity, or record an explicit standalone run."""
    candidates: list[Path] = [root / "scripts" / "issue" / "goal_lineage.py"]
    here = Path(__file__).resolve()
    candidates.extend(
        ancestor / "scripts" / "issue" / "goal_lineage.py" for ancestor in (here, *here.parents)
    )
    lineage_path = next((candidate for candidate in candidates if candidate.is_file()), None)
    if lineage_path is None:
        raise RunReviewError("runtime-unavailable", "scripts/issue/goal_lineage.py is not available")
    module = load_module(lineage_path, "charness_run_review_goal_lineage")
    try:
        if path_value is None:
            return module.not_goal_bound_lineage(reason)
        loaded = module.load_goal_lineage_file(root, Path(path_value))
        return module.require_goal_execution_identity(loaded)
    except module.LineageError as exc:
        raise RunReviewError("invalid-lineage", str(exc), details=exc.as_dict()) from exc


ATTEMPT_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$")


def attempt_id(value: str | None) -> str:
    candidate = value or f"review-{datetime.now().strftime('%Y%m%dT%H%M%SZ')}-{os.getpid()}"
    if not ATTEMPT_RE.fullmatch(candidate):
        raise RunReviewError("input-invalid", "attempt-id must be a short path-safe identifier")
    return candidate


def run_command(command: list[str], *, root: Path, timeout: float = 60.0) -> tuple[int, str, str]:
    try:
        result = run_process(command, cwd=root, timeout_seconds=timeout)
    except OSError as exc:
        raise RunReviewError(
            "runner-invalid", f"command could not complete: {' '.join(command)}: {exc}"
        ) from exc
    return result.returncode, result.stdout, result.stderr


def resolve_adapter(root: Path, resolver: Path) -> dict[str, Any]:
    try:
        module = load_module(resolver, "charness_run_review_resolve_adapter")
        payload = module.load_adapter(root)
    except Exception as exc:
        raise RunReviewError(
            "adapter-invalid", f"critique adapter could not be resolved: {exc}"
        ) from exc
    if not isinstance(payload, dict) or payload.get("valid") is not True:
        details = {"adapter": payload} if isinstance(payload, dict) else {}
        raise RunReviewError("adapter-invalid", "critique adapter is invalid", details=details)
    return payload


def select_backend(
    adapter: dict[str, Any], requested: str | None, *, dry_run: bool
) -> tuple[str | None, int]:
    data = adapter.get("data")
    runner = data.get("reviewer_runner") if isinstance(data, dict) else None
    runner = runner if isinstance(runner, dict) else {}
    if runner.get("mode", "file-backed-worker") != "file-backed-worker":
        raise RunReviewError(
            "typed-subagent-selected", "adapter selected typed-subagent; use the host spawn branch"
        )
    configured = runner.get("backend", "host-defaulted")
    if requested is not None and configured != "host-defaulted" and requested != configured:
        raise RunReviewError("runner-invalid", f"adapter backend {configured!r} is authoritative")
    if configured != "host-defaulted":
        backend = requested or configured
    elif requested:
        backend = requested
    elif dry_run:
        backend = None
    elif shutil.which("codex"):
        backend = "codex_exec"
    elif shutil.which("claude"):
        backend = "claude_p"
    else:
        raise RunReviewError(
            "backend-unavailable", "host-defaulted adapter has no codex or claude executable"
        )
    timeout = runner.get("timeout_seconds", 900)
    if type(timeout) is not int or timeout <= 0:
        raise RunReviewError(
            "adapter-invalid", "reviewer_runner.timeout_seconds must be a positive integer"
        )
    return backend, timeout


def new_run_owner(root: Path, attempt: str) -> Any:
    """Open a repo-local reviewer scratch owner for the worker path contract."""
    run_id = "review-" + hashlib.sha256(attempt.encode("utf-8")).hexdigest()[:32]
    owner = owned_scratch(
        root,
        "critique-review",
        run_id=run_id,
        runtime_root_path=root / ".charness",
    )
    try:
        owner.open()
    except OSError as exc:
        raise RunReviewError("scratch-unavailable", f"cannot open reviewer scratch root: {exc}") from exc
    return owner


def run_runner(
    command: list[str], *, root: Path, stdout_path: Path, stderr_path: Path, timeout: int
) -> tuple[int | None, str, bool, str | None]:
    grace = max(2.0, min(30.0, timeout * 0.25))
    previous: dict[int, object] = {}

    def interrupt(_signum: int, _frame: object) -> None:
        raise KeyboardInterrupt

    try:
        for signum in (signal.SIGTERM, signal.SIGINT):
            try:
                previous[signum] = signal.signal(signum, interrupt)
            except (ValueError, OSError):
                continue
        outcome = run_monitored_phase(
            command, cwd=root, phase="critique-review-runner", timeout_seconds=timeout + grace
        )
        stdout_path.write_text(outcome.stdout, encoding="utf-8")
        stderr_path.write_text(outcome.stderr, encoding="utf-8")
        if outcome.timed_out:
            return (
                124,
                "runner-timeout",
                True,
                f"canonical runner exceeded {timeout + grace:g} seconds",
            )
        return outcome.returncode, "runner-completed", True, None
    except KeyboardInterrupt:
        return (
            130,
            "runner-interrupted",
            True,
            "canonical runner interrupted; worker group terminated",
        )
    except OSError as exc:
        return None, "runner-invalid", False, str(exc)
    finally:
        for signum, handler in previous.items():
            try:
                signal.signal(signum, handler)
            except (ValueError, OSError):
                pass


def run_runner_held_out(
    command: list[str],
    *,
    root: Path,
    stdout_path: Path,
    stderr_path: Path,
    timeout: int,
    hold_out_paths: list[str],
) -> tuple[int | None, str, bool, str | None]:
    with hold_out(root, hold_out_paths):
        return run_runner(
            command, root=root, stdout_path=stdout_path, stderr_path=stderr_path, timeout=timeout
        )


def load_mapping(path: Path) -> dict[str, Any] | None:
    if not path.is_file():
        return None
    try:
        payload = yaml.safe_load(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, yaml.YAMLError):
        return None
    return payload if isinstance(payload, dict) else None


def classify_runner_output(
    path: Path, *, returncode: int | None, status: str, started: bool, error: str | None
) -> tuple[int | None, str, bool, str | None]:
    payload = load_mapping(path)
    if isinstance(payload, dict) and payload.get("status") == "runner-invalid":
        return (
            returncode,
            "runner-invalid",
            False,
            str(payload.get("error") or error or "canonical runner refused the run"),
        )
    return returncode, status, started, error

"""Repository I/O and provenance-chain checks for worker report carriers."""

from __future__ import annotations

import hashlib
import importlib.util
import json
import sys
from pathlib import Path
from typing import Any


def _load_delivery_fields():
    candidate = Path(__file__).resolve().with_name("reviewer_delivery_fields.py")
    if not candidate.is_file():
        raise ImportError(f"package-local delivery-fields helper not found: {candidate}")
    spec = importlib.util.spec_from_file_location("charness_reviewer_delivery_fields", candidate)
    if spec is None or spec.loader is None:
        raise ImportError(f"unable to load package-local helper: {candidate}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module.PARENT_RECEIPT_ID_RE


PARENT_RECEIPT_ID_RE = _load_delivery_fields()
EXPECTED_PACKET_KIND = "charness.critique_prepare_packet"


def _load_result_contract():
    here = Path(__file__).resolve()
    for ancestor in (here.parent, *here.parents):
        candidate = ancestor / "reviewer_result_contract.py"
        if candidate.is_file():
            spec = importlib.util.spec_from_file_location("charness_reviewer_result_contract", candidate)
            if spec is not None and spec.loader is not None:
                module = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(module)
                return module
    raise ImportError("package reviewer_result_contract.py not found")


def _load_capability_contract():
    candidate = Path(__file__).resolve().with_name("reviewer_capability.py")
    module_name = "charness_reviewer_capability"
    spec = importlib.util.spec_from_file_location(module_name, candidate)
    if spec is None or spec.loader is None:
        raise ImportError(f"package reviewer_capability.py not found: {candidate}")
    module = importlib.util.module_from_spec(spec)
    previous = sys.modules.get(module_name)
    sys.modules[module_name] = module
    try:
        spec.loader.exec_module(module)
    finally:
        if previous is None:
            sys.modules.pop(module_name, None)
        else:
            sys.modules[module_name] = previous
    return module


def _load_delivery_attempt_parser():
    package_dir = Path(__file__).resolve().parent
    aliases = {
        "reviewer_delivery_fields": package_dir / "reviewer_delivery_fields.py",
        "reviewer_delivery_history": package_dir / "reviewer_delivery_history.py",
        "reviewer_delivery_schema": package_dir / "reviewer_delivery_schema.py",
        "reviewer_delivery_attempt_codec": package_dir / "reviewer_delivery_attempt_codec.py",
        "reviewer_delivery_attempt": package_dir / "reviewer_delivery_attempt.py",
    }
    saved: dict[str, object] = {}
    loaded: dict[str, object] = {}
    try:
        for public_name, path in aliases.items():
            spec = importlib.util.spec_from_file_location(f"charness_{public_name}", path)
            if spec is None or spec.loader is None:
                raise ImportError(f"unable to load package-local helper: {path}")
            module = importlib.util.module_from_spec(spec)
            sys.modules[f"charness_{public_name}"] = module
            saved[public_name] = sys.modules.get(public_name)
            sys.modules[public_name] = module
            spec.loader.exec_module(module)
            loaded[public_name] = module
        return loaded["reviewer_delivery_attempt"].DeliveryAttempt
    finally:
        for public_name, previous in saved.items():
            if previous is None:
                sys.modules.pop(public_name, None)
            else:
                sys.modules[public_name] = previous


def _load_identity_verifier():
    for ancestor in list(Path(__file__).resolve().parents)[:6]:
        candidate = ancestor / "scripts" / "review" / "reviewed_input_verification.py"
        if candidate.is_file():
            spec = importlib.util.spec_from_file_location("charness_reviewed_input_verification", candidate)
            if spec is not None and spec.loader is not None:
                module = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(module)
                return module
    return None


class WorkerCarrierError(ValueError):
    """The supplied artifact cannot prove a delivered worker approval."""


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


HIDDEN_RUNTIME_ROOTS = frozenset({".charness", ".artifacts"})


def _hidden_runtime_relative(rel: Path) -> bool:
    """True when the carrier sits in Variable Hidden Knowledge (`docs/artifact-policy.md`)."""
    return bool(rel.parts) and rel.parts[0] in HIDDEN_RUNTIME_ROOTS


def _report_path(repo_root: Path, value: str, *, allow_hidden: bool = False) -> Path:
    report_path = Path(value.strip().strip("`"))
    if not report_path.is_absolute() and ".." in report_path.parts:
        raise WorkerCarrierError("worker report path must be a safe repo-relative path without traversal, or an absolute path resolved inside the repository")
    resolved_root = repo_root.resolve()
    report_file = (report_path if report_path.is_absolute() else resolved_root / report_path).resolve()
    try:
        rel = report_file.relative_to(resolved_root)
    except ValueError as exc:
        raise WorkerCarrierError(f"worker report carrier path resolves outside the repository: {value}") from exc
    cited_hidden = (not report_path.is_absolute() and _hidden_runtime_relative(report_path)) or _hidden_runtime_relative(rel)
    if cited_hidden and not allow_hidden:
        raise WorkerCarrierError(
            f"worker report carrier is hidden runtime, not a durable tracked copy: {value}. "
            "Promote worker-report.yaml under charness-artifacts/critique/workers/<attempt>/ and cite that path."
        )
    if not report_file.is_file():
        raise WorkerCarrierError(f"worker report carrier does not exist inside the repository: {value}")
    return report_file


def _read_json(path: Path, label: str) -> dict[str, Any]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise WorkerCarrierError(f"{label} is not readable JSON: {exc}") from exc
    if not isinstance(payload, dict):
        raise WorkerCarrierError(f"{label} must contain a mapping")
    return payload


def _validate_packet_binding(
    *,
    repo_root: Path,
    artifact_binding_fields: dict[str, str],
    required_issue_numbers: list[int] | None = None,
    required_repository: str | None = None,
) -> dict[str, Any]:
    """Verify the generic packet/input identity and return its parsed bytes.

    The optional issue arguments remain accepted for compatibility with older
    callers, but issue membership is intentionally not interpreted here.  A
    consumer that owns target semantics must validate the returned packet.
    """
    packet_path = artifact_binding_fields.get("packet path", "").strip().strip("`")
    if not packet_path:
        raise WorkerCarrierError("worker-delivered requires the Reviewed Input Identity packet path")
    verifier = _load_identity_verifier()
    if verifier is None:
        raise WorkerCarrierError("package reviewed-input verifier is unavailable")
    try:
        packet = _read_json(_report_path(repo_root, packet_path), "reviewed packet")
        ok, reason = verifier.verify_packet_binding(
            repo_root=repo_root,
            packet_path=packet_path,
            packet_sha256=artifact_binding_fields.get("packet sha256", "").strip().lower(),
            identity_sha256=artifact_binding_fields.get("identity sha256", "").strip().lower(),
            expected_kind=EXPECTED_PACKET_KIND,
            check_current=True,
        )
    except (OSError, KeyError, TypeError, ValueError) as exc:
        raise WorkerCarrierError(f"reviewed packet binding could not be verified: {exc}") from exc
    if not ok:
        raise WorkerCarrierError(f"reviewed packet binding is not current: {reason}")
    return packet


def _validate_receipt_and_result(
    *, repo_root: Path, report: dict[str, Any], require_pass: bool = True
) -> tuple[dict[str, Any], dict[str, Any], str]:
    receipt_value = report.get("receipt_path")
    if not isinstance(receipt_value, str):
        raise WorkerCarrierError("worker report has no repo-readable receipt path")
    receipt = _read_json(_report_path(repo_root, receipt_value, allow_hidden=True), "worker receipt")
    if receipt.get("schema_version") != "charness.reviewer_worker.v1":
        raise WorkerCarrierError("worker receipt has the wrong schema")
    if receipt.get("status") != "succeeded" or receipt.get("terminal") is not True:
        raise WorkerCarrierError("worker receipt is not a terminal succeeded receipt")
    if receipt.get("exit_code") != 0 or receipt.get("output_fresh") is not True:
        raise WorkerCarrierError("worker receipt does not prove a fresh successful result")
    try:
        capability_contract = _load_capability_contract()
        capability_contract.validate_receipt_capabilities(
            receipt, attempt_id=str(report.get("attempt_id", ""))
        )
    except (ImportError, ValueError) as exc:
        raise WorkerCarrierError(f"worker receipt capability envelope is not valid: {exc}") from exc
    output_value = receipt.get("output_file")
    if not isinstance(output_value, str):
        raise WorkerCarrierError("worker receipt has no output file")
    output = _report_path(repo_root, output_value, allow_hidden=True)
    output_hash = _sha256(output)
    if output_hash != receipt.get("output_sha256") or output.stat().st_size != receipt.get("output_size"):
        raise WorkerCarrierError("worker output does not match the typed receipt hash/size")
    try:
        result = _load_result_contract().validate_bounded_result(
            output,
            packet_identity=str(report.get("packet_identity", "")),
            reviewed_input_identity=str(report.get("reviewed_input_identity", "")),
            require_pass=require_pass,
        )
    except (ImportError, ValueError) as exc:
        raise WorkerCarrierError(str(exc)) from exc
    try:
        capability_contract.validate_result_capability_non_claims(result, receipt)
    except (ImportError, ValueError) as exc:
        raise WorkerCarrierError(f"worker result capability non-claims are not approval-eligible: {exc}") from exc
    for field in ("capability_non_claims", "capability_non_claims_sha256"):
        if report.get(field) != receipt.get(field):
            raise WorkerCarrierError(f"worker report {field} does not match the worker receipt")
    if report.get("findings_identity") != output_hash or report.get("receipt_output_sha256") != output_hash:
        raise WorkerCarrierError("worker findings identity does not match the typed result")
    return receipt, result, output_hash


def _validate_joined_fields(
    *, attempt: Any, report: dict[str, Any], receipt: dict[str, Any], provenance: dict[str, Any]
) -> None:
    joined_fields = (
        "attempt_id", "scope", "packet_identity", "reviewed_input_identity",
        "parent_receipt_identity", "boundary_mode", "boundary_fingerprint", "execution_mode",
        "backend", "prompt_sha256", "schema_sha256",
        "capability_launch_envelope_sha256",
    )
    if report.get("attempt_id") != provenance.get("attempt_id"):
        raise WorkerCarrierError("delivery chain attempt_id does not match report provenance")
    if provenance.get("capability_non_claims_sha256") != report.get("capability_non_claims_sha256"):
        raise WorkerCarrierError("delivery chain capability non-claim digest does not match report provenance")
    for field in joined_fields:
        expected = provenance.get(field) if field == "attempt_id" else report.get(field)
        actual = getattr(attempt, field, None)
        if field == "boundary_fingerprint" and expected is None:
            if actual is not None or receipt.get(field) is not None or provenance.get(field) is not None:
                raise WorkerCarrierError(
                    "delivery chain boundary_fingerprint is present for a boundary mode that does not require it"
                )
            continue
        observed_receipt = receipt.get(field)
        if field == "boundary_mode" and observed_receipt is None and receipt.get("boundary_fingerprint") is not None:
            observed_receipt = "shared-tree-fingerprint"
        if expected is None or actual != expected or observed_receipt != expected:
            raise WorkerCarrierError(f"delivery chain {field} does not match report, receipt, and ledger attempt")
        if field != "attempt_id" and provenance.get(field) != expected:
            raise WorkerCarrierError(f"delivery chain {field} does not match report provenance")


def _validate_ledger(
    *, repo_root: Path, report: dict[str, Any], receipt: dict[str, Any], output_hash: str
) -> None:
    ledger_value = report.get("ledger_path")
    provenance = report.get("provenance")
    if not isinstance(ledger_value, str):
        raise WorkerCarrierError("worker report has no repo-readable ledger path")
    if not isinstance(provenance, dict) or not provenance.get("attempt_id"):
        raise WorkerCarrierError("worker report has no typed attempt provenance")
    ledger = _read_json(_report_path(repo_root, ledger_value, allow_hidden=True), "delivery ledger")
    if ledger.get("schema_version") != "charness.reviewer_delivery.v1":
        raise WorkerCarrierError("delivery ledger has the wrong schema")
    attempts = ledger.get("attempts")
    if not isinstance(attempts, list):
        raise WorkerCarrierError("delivery ledger has no attempts list")
    raw_attempt = next((item for item in attempts if isinstance(item, dict) and item.get("attempt_id") == provenance["attempt_id"]), None)
    if raw_attempt is None:
        raise WorkerCarrierError("delivery ledger does not contain the report attempt")
    try:
        attempt = _load_delivery_attempt_parser().from_dict(raw_attempt)
    except (ImportError, ValueError, TypeError, KeyError) as exc:
        raise WorkerCarrierError(f"delivery ledger canonical history is invalid: {exc}") from exc
    _validate_joined_fields(attempt=attempt, report=report, receipt=receipt, provenance=provenance)
    aliases = {
        "attempt_scope": report.get("scope"),
        "attempt_packet_identity": report.get("packet_identity"),
        "attempt_parent_receipt_identity": report.get("parent_receipt_identity"),
        "result_packet_identity": report.get("packet_identity"),
        "result_reviewed_input_identity": report.get("reviewed_input_identity"),
    }
    mismatches = [key for key, expected in aliases.items() if provenance.get(key) != expected]
    if mismatches:
        raise WorkerCarrierError(f"delivery chain provenance aliases do not match the report: {mismatches}")
    if attempt.state != "findings-received" or attempt.terminal is not True or not attempt.findings_identity:
        raise WorkerCarrierError("delivery ledger does not prove findings-received completion")
    if attempt.findings_identity != output_hash:
        raise WorkerCarrierError("delivery ledger findings identity does not match the result")


def _validate_delivery_chain(
    *, repo_root: Path, report: dict[str, Any], require_pass: bool = True
) -> tuple[dict[str, Any], dict[str, Any], str]:
    receipt, result, output_hash = _validate_receipt_and_result(
        repo_root=repo_root, report=report, require_pass=require_pass
    )
    _validate_ledger(repo_root=repo_root, report=report, receipt=receipt, output_hash=output_hash)
    return receipt, result, output_hash


def _assert_expected_path(
    repo_root: Path, value: object, expected: Path, label: str
) -> None:
    if not isinstance(value, str):
        raise WorkerCarrierError(f"worker report has no {label} path")
    actual = _report_path(repo_root, value, allow_hidden=True)
    if actual != expected.resolve():
        raise WorkerCarrierError(f"worker {label} path is not bound to the retained attempt")


def validate_delivered_worker_report(
    *,
    repo_root: Path,
    report: dict[str, Any],
    expected_attempt_id: str | None = None,
    expected_paths: dict[str, Path] | None = None,
) -> tuple[dict[str, Any], dict[str, Any], str]:
    """Validate a delivered typed result without converting it into approval.

    A critique round records findings, so a typed ``block`` or ``defer`` is a
    valid delivered result even though the approval consumer must reject it.
    The report remains delivery evidence; the typed result bytes remain the
    findings carrier. Requiring this chain makes a same-context raw text file
    impossible to submit as a reviewer round.
    """
    expected = {
        "schema_version": "charness.reviewer_worker_report.v1",
        "delivery_state": "findings-received",
        "collection_ready": True,
        "provenance_ok": True,
        "receipt_ok": True,
        "ledger_ok": True,
        "result_schema_ok": True,
    }
    mismatches = [
        f"{field}={report.get(field)!r} (expected {value!r})"
        for field, value in expected.items()
        if report.get(field) != value
    ]
    if mismatches:
        raise WorkerCarrierError(
            "worker report is not a delivered typed result: " + "; ".join(mismatches)
        )
    if expected_attempt_id is not None and report.get("attempt_id") != expected_attempt_id:
        raise WorkerCarrierError("worker report attempt_id is not bound to the retained attempt")
    if report.get("execution_mode") not in ("file-backed-worker", "typed-subagent"):
        raise WorkerCarrierError("worker report has no supported distinct execution mode")
    for field in (
        "attempt_id",
        "producer_run_id",
        "scope",
        "packet_identity",
        "reviewed_input_identity",
        "parent_receipt_identity",
        "boundary_mode",
        "findings_identity",
        "receipt_output_sha256",
    ):
        if not isinstance(report.get(field), str) or not report[field].strip():
            raise WorkerCarrierError(f"worker report has no explicit {field}")
    receipt, result, output_hash = _validate_delivery_chain(
        repo_root=repo_root, report=report, require_pass=False
    )
    if expected_paths is not None:
        _assert_expected_path(repo_root, report.get("receipt_path"), expected_paths["receipt"], "receipt")
        _assert_expected_path(repo_root, report.get("ledger_path"), expected_paths["delivery"], "ledger")
        _assert_expected_path(repo_root, receipt.get("output_file"), expected_paths["result"], "result")
    return receipt, result, output_hash

"""Candidate preservation, proof readiness, and retention at task completion."""

from __future__ import annotations

from pathlib import Path
from types import SimpleNamespace
from typing import Any

import pytest

from scripts.task_run import task_run_completion, task_run_git
from tests.quality_gates.repo_shapes import install_committed_repo


def _complete(
    tmp_path: Path,
    *,
    candidate_kind: str = "clean",
    result_state: str | None = None,
    scope_verdict: str = "pass",
    changed_line_gate: Any = None,
    execution_state: str = "completed",
    parent_blocking: bool = False,
    git: Any = None,
    persist_events: list[str] | None = None,
) -> dict[str, Any]:
    target = install_committed_repo(tmp_path / "worktree", {"module.py": "VALUE = 1\n"})
    base_sha = task_run_git._git_output(target, "rev-parse", "HEAD").strip()
    if candidate_kind == "clean":
        (target / "module.py").write_text("VALUE = 2\n", encoding="utf-8")
        task_run_git._commit_lane_snapshot(target, message="test candidate")
    elif candidate_kind == "dirty":
        (target / "module.py").write_text("VALUE = 2\n", encoding="utf-8")
    elif candidate_kind != "absent":
        raise AssertionError(f"unknown candidate fixture: {candidate_kind}")
    branch = task_run_git._git_output(target, "symbolic-ref", "--quiet", "--short", "HEAD").strip()
    carrier = task_run_git._candidate_carrier(target, base_sha, branch=branch)
    useful = candidate_kind != "absent"
    candidate = {
        "status": "validated" if useful else "absent",
        "useful": useful,
        **carrier,
    }
    if result_state is None:
        result_state = "validated-partial-result" if parent_blocking else "completed"
    evidence = {"populations": {}}
    scope = {"verdict": scope_verdict, "reason": "scope drifted"}
    parent_progress = {
        "blocking": parent_blocking,
        "classification": "writer-conflict" if parent_blocking else "no-parent-progress",
    }

    def default_git(cwd: Path, *args: str) -> Any:
        if args[:2] == ("worktree", "remove"):
            return SimpleNamespace(returncode=1, stdout="", stderr="not removing the unit fixture")
        if persist_events is not None and "commit" in args:
            persist_events.append("persist-commit")
        return task_run_git._git(cwd, *args)

    return task_run_completion.complete_task(
        {"task_id": "lane-1", "target_branch": branch, "base_sha": base_sha},
        runtime_path=tmp_path / "runtime",
        resolved_target=target,
        resolved_repo=target,
        before_exec={},
        base_sha=base_sha,
        scope_specs=[],
        require_change=False,
        parent_before={},
        parent_before_head=base_sha,
        stdout_log=tmp_path / "stdout.log",
        execution={},
        started_at=0.0,
        persist=lambda _payload, _path: None,
        result_delivery=lambda _log: {"status": "delivered"},
        completion_evidence=lambda **_kwargs: (
            {**evidence, "scope": scope},
            {
                "verdict": scope_verdict,
                "reason": "scope drifted",
                "changed_paths": carrier["changed_paths"],
                "candidate_carrier": carrier,
            },
            parent_progress,
        ),
        execution_state=lambda _execution, _delivery: execution_state,
        candidate_result_state=lambda **_kwargs: (candidate, result_state),
        candidate_commit=None,
        git=git or default_git,
        git_output=task_run_git._git_output,
        pass_value="pass",
        changed_line_gate=changed_line_gate,
    )


def test_dirty_useful_work_is_persisted_before_the_gate_sees_a_clean_candidate(
    tmp_path: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    events: list[Any] = []

    def gate(worktree: Path, *, base_sha: str, log_dir: Path) -> dict[str, Any]:
        events.append(
            (
                "gate",
                task_run_git._git_output(worktree, "rev-parse", "HEAD").strip(),
                task_run_git._git_output(worktree, "status", "--porcelain").strip(),
                base_sha,
                log_dir,
            )
        )
        return {"status": "clean", "blocking": False, "summary": "gate clean"}

    payload = _complete(
        tmp_path,
        candidate_kind="dirty",
        changed_line_gate=gate,
        persist_events=events,
    )

    assert events[0] == "persist-commit"
    assert events[1][0] == "gate"
